  learner: (dir) => `c.learner_name COLLATE NOCASE ${dir}, c.id ${dir}`,
  course: (dir) => `c.course_title COLLATE NOCASE ${dir}, c.id ${dir}`,
  serial: (dir) => `c.serial_number ${dir}, c.id ${dir}`,
  status: (dir) => `c.status ${dir}, c.id ${dir}`,
