    const courses = COURSE_TITLES.map((title) => ({
      title,
      id: db.run(
        'INSERT INTO courses (tenant_id, title, is_generated, created_at) VALUES (@tenantId, @title, 1, @createdAt)',
        { tenantId: tenant.id, title, createdAt },
