      let ended = false;
      let finish;
      const whole = new Promise((done, failed) => {
        finish = done;
        res.on('error', failed);
      });
      res.on('end', () => {
        ended = true;
        finish(Buffer.concat(chunks).toString('utf8'));
      });
      res.on('data', (chunk) => {
        chunks.push(chunk);
        bytes += chunk.length;
      });
      res.once('data', () => {
        res.pause();
        resolve({
          status: res.statusCode,
          headers: res.headers,
          bytesSoFar: () => bytes,
          finished: () => ended,
          resume: () => {
            res.resume();
            return whole;
          },
        });
      });
    });
    req.on('error', reject);
  });
}

