.muted {
  color: var(--muted);
}

.small {
  font-size: 0.85rem;
}

.mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.92em;
}

.nowrap {
  white-space: nowrap;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Layout ------------------------------------------------------------------------------------ */

.app {
  min-height: 100vh;
}

.boot {
  max-width: 560px;
  margin: 20vh auto 0;
  padding: 0 1rem;
  text-align: center;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  padding: 0.6rem 1.5rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 5;
}

.topbar-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 650;
}

.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 6px;
  background: var(--primary);
  color: #fff;
  font-size: 0.95rem;
}

.tabs {
  display: flex;
  gap: 0.25rem;
  flex: 1;
}

.tab {
  padding: 0.45rem 0.85rem;
  border-radius: 6px;
  color: var(--muted);
  text-decoration: none;
  font-weight: 550;
}

.tab:hover {
  background: var(--bg);
  color: var(--text);
}

.tab-active,
.tab-active:hover {
  background: var(--info-bg);
  color: var(--info-text);
}

.topbar-actor {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.tenant-chip {
  display: flex;
  flex-direction: column;
  padding: 0.2rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  line-height: 1.2;
}

.tenant-name {
  font-weight: 650;
}

.tenant-zone {
  font-size: 0.78rem;
  color: var(--muted);
}

.actor-select {
  display: flex;
  flex-direction: column;
  font-size: 0.78rem;
  color: var(--muted);
}

.content {
  max-width: 1180px;
  margin: 0 auto;
  padding: 1.25rem 1.5rem 3rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.1rem 1.25rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Controls ---------------------------------------------------------------------------------- */

.toolbar {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  align-items: flex-end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.field-grow {
  flex: 1 1 260px;
}

.field-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
}

input,
select,
textarea,
button {
  font: inherit;
  color: inherit;
}

input[type='search'],
select,
textarea {
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  background: #fff;
  min-height: 2.25rem;
  max-width: 100%;
}

textarea {
  width: 100%;
  resize: vertical;
}

input:focus-visible,
select:focus-visible,
textarea:focus-visible,
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 2.25rem;
  padding: 0.4rem 0.9rem;
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  background: #fff;
  font-weight: 550;
  text-decoration: none;
  color: var(--text);
  cursor: pointer;
  white-space: nowrap;
}

.btn:hover:not(:disabled) {
  background: var(--bg);
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.btn-small {
  min-height: 1.9rem;
  padding: 0.2rem 0.6rem;
  font-size: 0.88rem;
}

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  background: var(--primary-dark);
}

.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.btn-danger:hover:not(:disabled) {
  background: var(--danger-dark);
}

.link {
  border: 0;
  padding: 0;
  background: none;
  color: var(--primary);
  text-decoration: underline;
  cursor: pointer;
}

.chips {
  display: flex;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.chip {
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  background: #fff;
  padding: 0.2rem 0.75rem;
  font-size: 0.88rem;
  cursor: pointer;
}

.chip-active {
  background: var(--info-bg);
  border-color: var(--primary);
  color: var(--info-text);
  font-weight: 600;
}

/* Tables ------------------------------------------------------------------------------------ */

.table-wrap {
  position: relative;
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 6px;
  min-height: 3rem;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
}

.data-table th,
.data-table td {
  padding: 0.55rem 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

.data-table thead th {
  background: #f8f9fc;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--muted);
  white-space: nowrap;
}

.data-table tbody tr:last-child td {
  border-bottom: 0;
}

.data-table.is-refreshing tbody {
  opacity: 0.45;
}

.th-button {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border: 0;
  padding: 0;
  background: none;
  font: inherit;
  font-weight: 700;
  text-transform: inherit;
  letter-spacing: inherit;
  color: inherit;
  cursor: pointer;
}

.th-hint {
  font-weight: 500;
  text-transform: none;
  letter-spacing: 0;
}

.sort-arrow {
  font-size: 0.7rem;
  opacity: 0.55;
}

th[aria-sort='ascending'] .sort-arrow,
th[aria-sort='descending'] .sort-arrow {
  opacity: 1;
  color: var(--primary);
}

.row-link {
  cursor: pointer;
}

.row-link:hover {
  background: #f6f8fd;
}

.row-selected,
.row-selected:hover {
  background: var(--info-bg);
}

.refreshing {
  position: absolute;
  top: 0.45rem;
  right: 0.6rem;
  padding: 0.15rem 0.6rem;
  border-radius: 999px;
  background: var(--surface);
  border: 1px solid var(--border);
  font-size: 0.85rem;
}

.pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.pagination-buttons {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.pagination-page {
  padding: 0 0.4rem;
  font-size: 0.9rem;
}

/* Status ------------------------------------------------------------------------------------ */

.badge {
  display: inline-block;
  padding: 0.05rem 0.55rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 650;
  white-space: nowrap;
}

.badge-active,
.badge-issued {
  background: var(--success-bg);
  color: var(--success-text);
}

.badge-revoked,
.badge-failed {
  background: var(--error-bg);
  color: var(--error-text);
}

.badge-skipped {
  background: var(--warn-bg);
  color: var(--warn-text);
}

.spinner-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.spinner {
  width: 1em;
  height: 1em;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation-duration: 2.5s;
  }
}

.state {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  flex-wrap: wrap;
  padding: 1.25rem;
  border-radius: 6px;
}

.state-body {
  flex: 1 1 240px;
}

.state-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.state-loading {
  justify-content: center;
  color: var(--muted);
  padding: 2.25rem 1rem;
}

.state-empty {
  background: #f8f9fc;
  border: 1px dashed var(--border-strong);
  color: var(--muted);
}

.state-empty strong {
  color: var(--text);
}

.table-wrap > .state-empty,
.table-wrap > .state-error {
  border: 0;
  border-radius: 0;
}

.state-error {
  background: var(--error-bg);
  border: 1px solid #f3c2bd;
  color: var(--error-text);
}

.state-icon {
  display: grid;
  place-items: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 50%;
  background: var(--danger);
  color: #fff;
  font-weight: 800;
}

.note {
  margin: 0;
  padding: 0.55rem 0.8rem;
  border-radius: 6px;
  background: var(--info-bg);
  color: var(--info-text);
}

.note-success {
  background: var(--success-bg);
  color: var(--success-text);
}

.note-error {
  background: var(--error-bg);
  color: var(--error-text);
}

.export-status:empty {
  display: none;
}

.tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 0.75rem;
}

.tile {
  display: flex;
  flex-direction: column;
  padding: 0.6rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #f8f9fc;
}

.tile-value {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.2;
}

.tile-label {
  font-size: 0.8rem;
  color: var(--muted);
}

.tile-issued {
  background: var(--success-bg);
  border-color: #bfe3cd;
}

.tile-skipped {
  background: var(--warn-bg);
  border-color: #f0dc9c;
}

.tile-failed {
  background: var(--error-bg);
  border-color: #f3c2bd;
}

/* Dialogs ----------------------------------------------------------------------------------- */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  background: rgba(16, 24, 40, 0.45);
}

.overlay-modal {
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 30;
}

.overlay-drawer {
  justify-content: flex-end;
}

.dialog {
  background: var(--surface);
  box-shadow: 0 12px 40px rgba(16, 24, 40, 0.25);
  outline: none;
}

.dialog-modal {
  width: min(520px, 100%);
  border-radius: var(--radius);
}

.dialog-drawer {
  width: min(520px, 100%);
  height: 100%;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.dialog-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
}

.drawer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.9rem 1.25rem;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--surface);
}

.drawer-body {
  padding: 1.1rem 1.25rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 0.9rem;
}

.detail-title {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.detail-serial {
  font-size: 1.25rem;
  font-weight: 700;
}

.detail-grid {
  margin: 0;
  display: grid;
  gap: 0.85rem;
}

.detail-field dt {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.detail-field dd {
  margin: 0.1rem 0 0;
}

.detail-actions {
  padding-top: 0.25rem;
}

.audit-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.audit-list li {
  padding: 0.55rem 0.75rem;
  border-left: 3px solid var(--border-strong);
  background: #f8f9fc;
  border-radius: 0 6px 6px 0;
}

@media (max-width: 720px) {
  .topbar {
    padding: 0.6rem 0.9rem;
    gap: 0.75rem;
  }

  .content {
    padding: 0.9rem 0.75rem 2.5rem;
  }

  .panel {
    padding: 0.9rem;
  }
}

input.command:
S=/tmp/claude-0/-home-user/61a877e9-483e-575a-b7cf-c5b8e94decb9/scratchpad && mkdir -p $S/shots && cat > $S/ui1.cjs <<'EOF'
const { chromium } = require('playwright');
const fs = require('fs');
const out = process.env.SHOTS;
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1280, height: 860 }, acceptDownloads: true });
  const page = await context.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));

  await page.goto('http://localhost:3000/');
  await page.waitForSelector('[data-testid="certificate-list"][data-state="success"]');
  console.log('title:', await page.title());
  console.log('tenant:', await page.textContent('[data-testid="tenant-name"]'));
  const rows = async () => page.$$eval('[data-testid="certificate-list"] tbody tr', (trs) => trs.map((tr) => [...tr.children].map((td) => td.innerText.trim()).join(' | ')));
  console.log('east rows:\n ' + (await rows()).join('\n '));
  await page.screenshot({ path: `${out}/01-list-east.png` });

  // search
  await page.fill('[data-testid="search-input"]', 'alex');
  await page.waitForFunction(() => document.querySelectorAll('[data-testid="certificate-list"] tbody tr').length === 1);
  console.log('search alex:', await rows());
  // empty state
  await page.fill('[data-testid="search-input"]', 'zzzz-no-such');
  await page.waitForSelector('.state-empty');
  console.log('empty state:', (await page.innerText('.state-empty')).replace(/\n/g, ' / '));
  await page.screenshot({ path: `${out}/02-empty.png` });
  await page.click('text=Clear search and filters');
  await page.waitForFunction(() => document.querySelectorAll('[data-testid="certificate-list"] tbody tr').length === 7);

  // sort via header
  await page.click('th >> text=Learner');
  await page.waitForFunction(() => document.querySelector('th[aria-sort="ascending"]')?.innerText.includes('LEARNER') || document.querySelector('th[aria-sort="ascending"]')?.innerText.toLowerCase().includes('learner'));
  await page.waitForSelector('[data-testid="certificate-list"][data-state="success"]');
  console.log('sorted by learner asc:', (await rows()).map((r) => r.split(' | ')[1]));
  console.log('sort select value:', await page.inputValue('[data-testid="sort-select"]'));

  // detail of Alex Lee
  await page.click('text=EAST-0000001');
  await page.waitForSelector('[data-testid="detail-serial"]');
  console.log('detail:', await page.textContent('[data-testid="detail-serial"]'), '|', await page.textContent('[data-testid="detail-status"]'), '|', await page.textContent('[data-testid="detail-issued-local"]'));
  console.log('url hash:', await page.evaluate(() => location.hash));
  await page.screenshot({ path: `${out}/03-detail.png` });

  // revoke: open confirm, cancel, then confirm
  await page.click('[data-testid="revoke-button"]');
  await page.waitForSelector('[data-testid="revoke-dialog"]');
  await page.screenshot({ path: `${out}/04-revoke-confirm.png` });
  await page.keyboard.press('Escape');
  await page.waitForSelector('[data-testid="revoke-dialog"]', { state: 'detached' });
  console.log('after escape: drawer still open =', !!(await page.$('[data-testid="detail-serial"]')), '| status =', await page.textContent('[data-testid="detail-status"]'));
  await page.click('[data-testid="revoke-button"]');
  await page.fill('[data-testid="revoke-reason"]', 'UI walkthrough');
  await page.click('[data-testid="revoke-confirm"]');
  await page.waitForSelector('[data-testid="revoke-result"]');
  console.log('revoke result:', await page.textContent('[data-testid="revoke-result"]'), '| status =', await page.textContent('[data-testid="detail-status"]'));
  console.log('audit trail:', (await page.$$eval('[data-testid="audit-trail"] li', (lis) => lis.map((li) => li.innerText.replace(/\n/g, ' — ')))));
  console.log('revoke button present after revoke:', !!(await page.$('[data-testid="revoke-button"]')));
  await page.screenshot({ path: `${out}/05-revoked.png` });
  await page.keyboard.press('Escape');
  await page.waitForSelector('[data-testid="detail-serial"]', { state: 'detached' });
  await page.waitForSelector('[data-testid="certificate-list"][data-state="success"]');
  console.log('list row after revoke:', (await rows()).find((r) => r.includes('EAST-0000001')));

  // export
  const [download] = await Promise.all([page.waitForEvent('download'), page.click('[data-testid="export-button"]')]);
  const file = `${out}/${download.suggestedFilename()}`;
  await download.saveAs(file);
  await page.waitForSelector('[data-testid="export-done"]');
  console.log('export note:', await page.textContent('[data-testid="export-done"]'));
  console.log('csv:\n' + fs.readFileSync(file, 'utf8'));

  // switch actor
  await page.selectOption('[data-testid="actor-select"]', 'bob@west.test');
  await page.waitForFunction(() => document.querySelector('[data-testid="tenant-name"]').textContent === 'West');
  await page.waitForSelector('[data-testid="certificate-list"][data-state="success"]');
  console.log('west rows:\n ' + (await rows()).join('\n '));
  await page.screenshot({ path: `${out}/06-list-west.png` });
  // cross-tenant deep link
  await page.goto('http://localhost:3000/#/certificates/1');
  await page.waitForSelector('[data-testid="certificate-detail"] .state-error');
  console.log('bob opening east cert #1:', (await page.innerText('[data-testid="certificate-detail"] .state-error')).replace(/\n/g, ' / '));
  await page.screenshot({ path: `${out}/07-cross-tenant.png` });

  console.log('errors:', errors);
  await browser.close();
})().catch((e) => { console.error('FAILED', e); process.exit(1); });
EOF
cd $S && SHOTS=$S/shots node ui1.cjs

