      }
      await sleep(delay);
      delay = Math.min(delay * 2, 100);
    }

    this.#depth = 1;
    let result;
    try {
      result = fn();
      if (result && typeof result.then === 'function') {
        throw new TypeError('Transaction callbacks must be synchronous');
      }
