/**
 * Thin, synchronous SQLite access layer.
 *
 * Two interchangeable drivers are supported behind one small interface:
 *   - `better-sqlite3` (preferred when its native binding is installed), and
 *   - `node:sqlite`, the driver built into Node.js >= 22.13 (zero-install fallback).
 *
 * Both are synchronous, which is what makes the write paths easy to reason about: a
 * transaction callback runs to completion without ever yielding to the event loop.
 * Cross-process safety does not depend on that, though - every write transaction is
 * `BEGIN IMMEDIATE`, so SQLite itself serialises writers.
 *
 * Set SQLITE_DRIVER=better-sqlite3 | node to force a specific driver.
 */
import fs from 'node:fs';
import path from 'node:path';

const BUSY_TIMEOUT_MS = 10_000;
/** How long a request waits for another process to release the write lock before answering 503. */
const WRITE_LOCK_WAIT_MS = 10_000;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** True when SQLite refused an operation because another connection holds the lock it needs. */
export function isBusyError(err) {
  if (!err) return false;
  if (typeof err.code === 'string' && err.code.startsWith('SQLITE_BUSY')) return true; // better-sqlite3
  if (typeof err.errcode === 'number' && (err.errcode & 0xff) === 5) return true; // node:sqlite (extended codes too)
  return /database is locked/i.test(String(err.message ?? ''));
}

async function loadBetterSqlite() {
  const mod = await import('better-sqlite3');
  const Database = mod.default ?? mod;
  new Database(':memory:').close(); // the native binding loads lazily; fail here, not on first use
  return {
    name: 'better-sqlite3',
    open: (file) => new Database(file),
  };
}

async function loadNodeSqlite() {
  // `node:sqlite` announces itself with an ExperimentalWarning on first import. It is a
  // deliberate, tested choice here, so keep that one notice out of the server log.
  const emitWarning = process.emitWarning;
  process.emitWarning = function patchedEmitWarning(warning, ...rest) {
    const type = typeof rest[0] === 'string' ? rest[0] : rest[0]?.type;
    const text = typeof warning === 'string' ? warning : warning?.message;
    if (type === 'ExperimentalWarning' && /sqlite/i.test(String(text))) return undefined;
    return emitWarning.call(process, warning, ...rest);
  };
  try {
    const { DatabaseSync } = await import('node:sqlite');
    return {
      name: 'node:sqlite',
      open: (file) => new DatabaseSync(file),
    };
  } finally {
    process.emitWarning = emitWarning;
  }
}

async function resolveDriver() {
  const preference = (process.env.SQLITE_DRIVER ?? 'auto').trim().toLowerCase();
  const wantBetter = preference === 'auto' || preference === 'better-sqlite3';
  const wantNode = preference === 'auto' || preference === 'node' || preference === 'node:sqlite';
  if (!wantBetter && !wantNode) {
    throw new Error(`Unsupported SQLITE_DRIVER "${preference}" (use "better-sqlite3" or "node")`);
  }

  const failures = [];
  if (wantBetter) {
    try {
      return await loadBetterSqlite();
    } catch (err) {
      failures.push(`better-sqlite3: ${err.message}`);
    }
  }
  if (wantNode) {
    try {
      return await loadNodeSqlite();
    } catch (err) {
      failures.push(`node:sqlite: ${err.message}`);
    }
  }
  throw new Error(
    'No SQLite driver could be loaded. Use Node.js >= 22.13 (built-in node:sqlite) or make sure the ' +
      `optional "better-sqlite3" dependency installed correctly.\n  - ${failures.join('\n  - ')}`,
  );
}

const driver = await resolveDriver();

export const driverName = driver.name;

/** Marks errors after which SQLite has already rolled the whole transaction back. */
export class TransactionAbortedError extends Error {
  constructor(cause) {
    super(`SQLite aborted the surrounding transaction: ${cause?.message ?? cause}`, { cause });
    this.name = 'TransactionAbortedError';
  }
}

export class Connection {
  #raw;
  #statements = new Map();
  #depth = 0;

  constructor(raw, file) {
    this.#raw = raw;
    this.file = file;
    this.driver = driver.name;
    this.open = true;
  }

  exec(sql) {
    this.#raw.exec(sql);
  }

  #statement(sql) {
    let statement = this.#statements.get(sql);
    if (!statement) {
      statement = this.#raw.prepare(sql);
      this.#statements.set(sql, statement);
    }
    return statement;
  }

  /**
   * Parameters are always a single object of named values (`@name` in SQL). Pass exactly the
   * names the statement uses: the two drivers disagree on how lenient to be about extras or
   * omissions, so being exact keeps behaviour identical on both.
   */
  get(sql, params) {
    const statement = this.#statement(sql);
    return params === undefined ? statement.get() : statement.get(params);
  }

  all(sql, params) {
    const statement = this.#statement(sql);
    return params === undefined ? statement.all() : statement.all(params);
  }

  run(sql, params) {
    const statement = this.#statement(sql);
    const info = params === undefined ? statement.run() : statement.run(params);
    return { changes: Number(info.changes), lastInsertRowid: Number(info.lastInsertRowid) };
  }

  /** Lazily steps through a result set. Uses a private statement so it never clashes with the cache. */
  iterate(sql, params) {
    const statement = this.#raw.prepare(sql);
    return params === undefined ? statement.iterate() : statement.iterate(params);
  }

  get inTransaction() {
    return this.#depth > 0;
  }

  /**
   * Runs `fn` atomically. The outermost call opens a transaction (IMMEDIATE by default, so the
   * write lock is taken up front and readers-turned-writers can never deadlock); nested calls
   * become SAVEPOINTs, which lets a caller contain the failure of one unit of work and carry on.
   */
  transaction(fn, { immediate = true } = {}) {
    const outermost = this.#depth === 0;
    const savepoint = `sp_${this.#depth}`;
    this.exec(outermost ? (immediate ? 'BEGIN IMMEDIATE' : 'BEGIN') : `SAVEPOINT ${savepoint}`);
    this.#depth += 1;

    let result;
    try {
      result = fn();
      if (result && typeof result.then === 'function') {
        throw new TypeError('Transaction callbacks must be synchronous');
      }
    } catch (err) {
      this.#depth -= 1;
      if (outermost) {
        try {
          this.exec('ROLLBACK');
        } catch {
          // SQLite already rolled back on its own (e.g. disk full); nothing left to undo.
        }
        throw err;
      }
      try {
        this.exec(`ROLLBACK TO ${savepoint}`);
        this.exec(`RELEASE ${savepoint}`);
      } catch (rollbackError) {
        // The savepoint is gone, which means the whole transaction is: do not let callers continue.
        throw err instanceof TransactionAbortedError ? err : new TransactionAbortedError(err ?? rollbackError);
      }
      throw err;
    }

    this.#depth -= 1;
    try {
      this.exec(outermost ? 'COMMIT' : `RELEASE ${savepoint}`);
    } catch (err) {
      if (outermost) {
        try {
          this.exec('ROLLBACK');
        } catch {
          // already rolled back
        }
        throw err;
      }
      throw new TransactionAbortedError(err);
    }
    return result;
  }

  /**
   * `transaction()` for request handlers: takes the write lock WITHOUT blocking the event loop.
   *
   * SQLite's own busy handler sleeps on the calling thread, which in Node is the thread that
   * serves every request. If another process holds the write lock (the load-test generator, a
   * reset, a second server), a plain BEGIN IMMEDIATE would therefore freeze all requests - reads
   * included - until it gets the lock. Here the lock is only ever *tried*; while it is taken, the
   * request waits asynchronously and the process keeps answering everything else. Once the lock is
   * held, `fn` runs synchronously to COMMIT exactly as in `transaction()`.
   */
  async writeTransaction(fn, { timeoutMs = WRITE_LOCK_WAIT_MS } = {}) {
    const deadline = Date.now() + timeoutMs;
    let delay = 4;
    for (;;) {
      if (this.#depth !== 0) throw new Error('writeTransaction cannot start inside another transaction');
      this.exec('PRAGMA busy_timeout = 0');
      try {
        this.exec('BEGIN IMMEDIATE');
        break;
      } catch (err) {
        if (!isBusyError(err) || Date.now() + delay > deadline) throw err;
      } finally {
        this.exec(`PRAGMA busy_timeout = ${BUSY_TIMEOUT_MS}`);
      }
      await sleep(delay);
      delay = Math.min(delay * 2, 100);
    }

    this.#depth = 1;
    let result;
    try {
      result = fn();
      if (result && typeof result.then === 'function') {
        throw new TypeError('Transaction callbacks must be synchronous');
      }
    } catch (err) {
      this.#depth = 0;
      try {
        this.exec('ROLLBACK');
      } catch {
        // SQLite already rolled back on its own
      }
      throw err;
    }
    this.#depth = 0;
    try {
      this.exec('COMMIT');
    } catch (err) {
      try {
        this.exec('ROLLBACK');
      } catch {
        // already rolled back
      }
      throw err;
    }
    return result;
  }

  close() {
    if (!this.open) return;
    this.open = false;
    this.#statements.clear();
    this.#raw.close();
  }
}

/**
 * Opens (and creates, if needed) the database file.
 *
 * WAL journaling is what lets a long CSV export hold a consistent read snapshot while list
 * requests and writes keep flowing: readers never block the writer and vice versa.
 *
 * `queryOnly` connections are used for exports; they cannot modify the database.
 */
export function openDatabase(file, { queryOnly = false } = {}) {
  if (!file || file === ':memory:') {
    throw new Error('A database file path is required (in-memory databases are not supported)');
  }
  const resolved = path.resolve(file);
  if (queryOnly) {
    if (!fs.existsSync(resolved)) throw new Error(`Database file does not exist: ${resolved}`);
  } else {
    fs.mkdirSync(path.dirname(resolved), { recursive: true });
  }

  const connection = new Connection(driver.open(resolved), resolved);
  connection.exec(`PRAGMA busy_timeout = ${BUSY_TIMEOUT_MS}`);
  connection.exec('PRAGMA foreign_keys = ON');
  if (queryOnly) {
    connection.exec('PRAGMA query_only = ON');
  } else {
    connection.exec('PRAGMA journal_mode = WAL');
    connection.exec('PRAGMA synchronous = NORMAL');
  }
  return connection;
}

/** Deletes a database file together with its WAL side files. */
export function removeDatabaseFiles(file) {
  const resolved = path.resolve(file);
  for (const suffix of ['', '-wal', '-shm']) {
    fs.rmSync(resolved + suffix, { force: true });
  }
}

/**
 * Bulk issue: one certificate for every eligible learner of a course, with per-learner outcomes.
 *
 * Retry safety
 * ------------
 * The whole operation - idempotency lookup, eligibility check, certificates, audit events and the
 * stored response - is ONE `BEGIN IMMEDIATE` transaction. SQLite admits a single writer at a time,
 * so identical requests racing each other (in this process or in another one sharing the file) are
 * strictly serialised: the first one executes and commits its response next to the idempotency
 * key, every later one finds that row and replays the stored response byte for byte. There is no
 * observable "in progress" state and therefore no window in which a duplicate could slip through.
 *
 * A crash before COMMIT leaves nothing behind (no certificates, no audit events, no key), so the
 * client's retry simply runs the operation for the first time.
 *
 * Independently of idempotency keys, UNIQUE (tenant_id, course_id, learner_id) on certificates
 * makes a second certificate for the same learner and course impossible.
 */
import { HttpError, badRequest, notFound } from '../lib/errors.js';
import { requestFingerprint } from '../lib/fingerprint.js';
import { pathId } from '../lib/params.js';
import { localDateTime } from '../lib/time.js';
import { TransactionAbortedError } from '../db/sqlite.js';
import { classifyEnrollment, findCourse, loadRoster } from './courses.js';
import { issueCertificate } from './ledger.js';

export const IDEMPOTENCY_HEADER = 'Idempotency-Key';
const ROUTE = '/api/bulk-issues';
const IDEMPOTENCY_KEY_PATTERN = /^[\x21-\x7E]{1,200}$/;

export function parseIdempotencyKey(headerValue) {
  if (headerValue === undefined) return null;
  const key = String(headerValue).trim();
  if (!IDEMPOTENCY_KEY_PATTERN.test(key)) {
    throw badRequest(`${IDEMPOTENCY_HEADER} must be 1-200 printable ASCII characters without spaces`);
  }
  return key;
}

function parseCourseId(body) {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    throw badRequest('Request body must be a JSON object such as {"courseId": 1}');
  }
  const value = body.courseId ?? body.course_id;
  const courseId = Number.isSafeInteger(value) && value > 0 ? value : pathId(typeof value === 'string' ? value : '');
  if (courseId === null) throw badRequest('"courseId" is required and must be a positive integer');
  return courseId;
}

function failureMessage(err) {
  const text = String(err?.message ?? err).replace(/\s+/g, ' ').trim();
  return `Certificate could not be issued: ${text.slice(0, 200) || 'unexpected error'}`;
}

/**
 * What an earlier request with this key left behind, if anything: its stored response when the
 * payload is the same, a 409 when it is not. Keys are scoped to (tenant, admin), so one actor can
 * never replay - or collide with - another actor's operation, let alone another tenant's.
 * `requestHash` null means "this request has no readable payload", which can only be a mismatch.
 */
function answerFromStoredKey(db, actor, idempotencyKey, requestHash) {
  if (idempotencyKey === null) return null;
  const previous = db.get(
    `SELECT id, request_hash, response_status, response_body
       FROM bulk_issue_operations
      WHERE tenant_id = @tenantId AND actor_admin_id = @adminId AND idempotency_key = @idempotencyKey`,
    { tenantId: actor.tenantId, adminId: actor.adminId, idempotencyKey },
  );
  if (!previous) return null;
  if (previous.request_hash !== requestHash) {
    throw new HttpError(
      409,
      'idempotency_key_reused',
      `${IDEMPOTENCY_HEADER} "${idempotencyKey}" was already used for a different request. ` +
        'Retry with the original payload, or use a new key for a new operation.',
      { operationId: previous.id },
    );
  }
  return { status: previous.response_status, body: previous.response_body, replayed: true, operationId: previous.id };
}

/**
 * For requests whose body could not even be parsed: if the key has already been used, this is a
 * reuse with a different payload (409); otherwise the caller reports the body error itself.
 */
export function rejectReusedKeyWithUnreadableBody(db, actor, idempotencyKey) {
  answerFromStoredKey(db, actor, idempotencyKey, null);
}

/**
 * Executes (or replays) a bulk issue.
 *
 * @returns {Promise<{ status: number, body: string, replayed: boolean, operationId: number }>}
 *   `body` is the JSON text of the operation; replays return the stored text unchanged.
 */
export async function bulkIssue(db, actor, { body, idempotencyKey }, { now = () => new Date(), hooks = {}, logger = console } = {}) {
  const requestHash = requestFingerprint('POST', ROUTE, body);

  // Fast path: a key that already ran is answered from a plain read (replay or 409). It needs no
  // write lock, so retries are served even while another process is in the middle of a long write.
  const stored = answerFromStoredKey(db, actor, idempotencyKey, requestHash);
  if (stored) return stored;

  // Obviously invalid requests are turned away before queueing for the write lock as well.
  if (!findCourse(db, actor, parseCourseId(body))) throw notFound('Course');

  return db.writeTransaction(() => {
    // 1. The decisive idempotency check, now under the write lock: an identical request that was
    //    racing this one has either not started (we execute) or has committed (we replay).
    const raced = answerFromStoredKey(db, actor, idempotencyKey, requestHash);
    if (raced) return raced;

    // 2. Validation. Nothing has been written yet, so a rejected request leaves no trace: no
    //    operation row, no idempotency record, no certificates, no audit events.
    const courseId = parseCourseId(body);
    const course = findCourse(db, actor, courseId);
    if (!course) throw notFound('Course'); // also the answer for another tenant's course

    // 3. Execute.
    const startedAt = now().toISOString();
    const tenant = { id: actor.tenantId, code: actor.tenantCode, timezone: actor.timezone };
    const operationId = db.run(
      `INSERT INTO bulk_issue_operations (tenant_id, actor_admin_id, course_id, idempotency_key, request_hash, status, created_at)
       VALUES (@tenantId, @adminId, @courseId, @idempotencyKey, @requestHash, 'running', @createdAt)`,
      {
        tenantId: actor.tenantId,
        adminId: actor.adminId,
        courseId: course.id,
        idempotencyKey,
        requestHash,
        createdAt: startedAt,
      },
    ).lastInsertRowid;

    const results = [];
    const summary = { total: 0, issued: 0, skipped: 0, failed: 0 };

    for (const row of loadRoster(db, actor.tenantId, course.id)) {
      const base = { learnerId: row.learner_id, learnerName: row.learner_name, enrollmentId: row.enrollment_id };
      const verdict = classifyEnrollment(row);
      summary.total += 1;

      if (!verdict.eligible) {
        summary.skipped += 1;
        const skipped = { ...base, outcome: 'skipped', reason: verdict.reason, message: verdict.message };
        if (row.certificate_id !== null) {
          skipped.certificateId = row.certificate_id;
          skipped.serialNumber = row.serial_number;
        }
        results.push(skipped);
        continue;
      }

      try {
        // Each learner gets a SAVEPOINT: if issuing fails for one of them, only that learner's
        // partial writes are undone and reported as "failed"; everyone else is unaffected.
        const certificate = db.transaction(() => {
          const learner = { id: row.learner_id, name: row.learner_name };
          hooks.beforeIssue?.({ learner, course, tenant });
          return issueCertificate(db, {
            tenant,
            actor,
            course,
            learner,
            enrollmentId: row.enrollment_id,
            issuedAt: startedAt,
            bulkOperationId: operationId,
            auditDetails: { enrollmentId: row.enrollment_id, idempotencyKey },
          });
        });
        summary.issued += 1;
        results.push({
          ...base,
          outcome: 'issued',
          certificateId: certificate.id,
          serialNumber: certificate.serialNumber,
          issuedAt: certificate.issuedAt,
          issuedLocal: localDateTime(certificate.issuedAt, actor.timezone),
        });
      } catch (err) {
        if (err instanceof TransactionAbortedError) throw err; // nothing can be salvaged; fail the request
        logger.error(`[bulk-issue] operation ${operationId}: learner ${row.learner_id} failed:`, err);
        summary.failed += 1;
        results.push({ ...base, outcome: 'failed', reason: 'issue_failed', message: failureMessage(err) });
      }
    }

    // 4. Store the response with the operation so every retry gets the identical answer.
    const status = 201;
    const completedAt = now().toISOString();
    const responseBody = JSON.stringify({
      id: operationId,
      status: 'completed',
      course,
      idempotencyKey,
      requestedBy: actor.email,
      tenant: { name: actor.tenantName, timezone: actor.timezone },
      createdAt: startedAt,
      completedAt,
      summary,
      results,
    });
    db.run(
      `UPDATE bulk_issue_operations
          SET status = 'completed', issued_count = @issued, skipped_count = @skipped, failed_count = @failed,
              response_status = @status, response_body = @body, completed_at = @completedAt
        WHERE id = @operationId`,
      {
        issued: summary.issued,
        skipped: summary.skipped,
        failed: summary.failed,
        status,
        body: responseBody,
        completedAt,
        operationId,
      },
    );

    return { status, body: responseBody, replayed: false, operationId };
  });
}

/** Stored result of a past operation (same JSON that the POST returned). 404 across tenants. */
export function getBulkOperation(db, actor, operationId) {
  const row =
    operationId === null
      ? undefined
      : db.get(
          `SELECT response_body FROM bulk_issue_operations
            WHERE id = @operationId AND tenant_id = @tenantId AND status = 'completed'`,
          { operationId, tenantId: actor.tenantId },
        );
  if (!row) throw notFound('Bulk issue operation');
  return row.response_body;
}

/** Most recent operations of the tenant, without the per-learner detail. */
export function listBulkOperations(db, actor, { limit = 10 } = {}) {
  return db
    .all(
      `SELECT o.id, o.course_id, c.title AS course_title, o.idempotency_key, o.issued_count, o.skipped_count,
              o.failed_count, o.created_at, a.email AS requested_by
         FROM bulk_issue_operations o
         JOIN courses c ON c.id = o.course_id
         JOIN admins a ON a.id = o.actor_admin_id
        WHERE o.tenant_id = @tenantId AND o.status = 'completed'
        ORDER BY o.id DESC
        LIMIT @limit`,
      { tenantId: actor.tenantId, limit },
    )
    .map((row) => ({
      id: row.id,
      status: 'completed',
      course: { id: row.course_id, title: row.course_title },
      idempotencyKey: row.idempotency_key,
      requestedBy: row.requested_by,
      createdAt: row.created_at,
      createdLocal: localDateTime(row.created_at, actor.timezone),
      summary: {
        total: row.issued_count + row.skipped_count + row.failed_count,
        issued: row.issued_count,
        skipped: row.skipped_count,
        failed: row.failed_count,
      },
    }));
}

#!/usr/bin/env node
/**
 * Database initialisation CLI.
 *
 *   node scripts/init-db.js           # create schema + demo data if the database is empty
 *   node scripts/init-db.js --reset   # restore the pristine quick-start dataset
 *
 * `--reset` empties and re-seeds the tables inside one transaction; it never deletes the file of
 * a usable database, so a server that has it open simply sees the fresh data afterwards. If
 * another process is in the middle of a long write, the reset gives up without changing anything.
 */
import fs from 'node:fs';
import { parseArgs } from 'node:util';

import { openInitializedDatabase } from '../src/bootstrap.js';
import { loadConfig, resolveUserPath } from '../src/config.js';
import { SCHEMA_VERSION } from '../src/db/schema.js';
import { seedDemoData } from '../src/db/seed.js';
import { isBusyError, openDatabase, removeDatabaseFiles } from '../src/db/sqlite.js';

const { values } = parseArgs({
  options: { reset: { type: 'boolean', default: false }, db: { type: 'string' } },
});

const dbPath = values.db ? resolveUserPath(values.db) : loadConfig().dbPath;

// Children before parents, so foreign keys stay satisfied at every step.
const TABLES_IN_DELETE_ORDER = [
  'audit_events',
  'certificates',
  'bulk_issue_operations',
  'enrollments',
  'learners',
  'courses',
  'admins',
  'tenants',
];

/** Returns 'done', 'empty' (nothing to reset yet) or 'incompatible' (file from another schema version). */
function resetInPlace() {
  const db = openDatabase(dbPath);
  try {
    const { user_version: version } = db.get('PRAGMA user_version');
    if (version === 0) return 'empty';
    if (version !== SCHEMA_VERSION) return 'incompatible';
    db.transaction(() => {
      for (const table of TABLES_IN_DELETE_ORDER) db.exec(`DELETE FROM ${table}`);
      seedDemoData(db);
    });
    try {
      db.exec('VACUUM'); // hand the space of removed load-test rows back to the file system
    } catch {
      // another connection is busy; the file is merely larger than necessary
    }
    return 'done';
  } finally {
    db.close();
  }
}

if (values.reset && fs.existsSync(dbPath)) {
  let outcome;
  try {
    outcome = resetInPlace();
  } catch (err) {
    // Never fall back to deleting the file here: a running server would keep writing to the
    // unlinked file and everything it acknowledged afterwards would be lost.
    if (isBusyError(err)) {
      console.error('The database is busy (another process is writing to it). Nothing was changed; try again in a moment.');
    } else {
      console.error(`Reset failed, nothing was changed: ${err.message}`);
    }
    process.exit(1);
  }
  if (outcome === 'done') {
    console.log(`Demo data restored in ${dbPath}`);
    process.exit(0);
  }
  if (outcome === 'incompatible') {
    console.log('The database file was created by a different version of this app; recreating it.');
    console.log('(If a server is still running on it, restart that server now.)');
    removeDatabaseFiles(dbPath);
  }
}

const db = openInitializedDatabase(dbPath, { log: console.log });
const counts = db.get(
  `SELECT (SELECT COUNT(*) FROM tenants) AS tenants, (SELECT COUNT(*) FROM courses) AS courses,
          (SELECT COUNT(*) FROM learners) AS learners, (SELECT COUNT(*) FROM certificates) AS certificates`,
);
console.log(
  `Database ready at ${dbPath}: ${counts.tenants} tenants, ${counts.courses} courses, ` +
    `${counts.learners} learners, ${counts.certificates} certificates.`,
);
db.close();

