content.content:
const { chromium } = require('playwright');
const out = process.env.SHOTS;
(async () => {
  const browser = await chromium.launch();
  const page = await (await browser.newContext({ viewport: { width: 1280, height: 900 } })).newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  const posts = [];
  page.on('request', (r) => { if (r.method() === 'POST' && r.url().includes('/api/bulk-issues')) posts.push(r.headers()['idempotency-key']); });

  // --- loading state: hold the first list response back
  let release;
  const gate = new Promise((resolve) => (release = resolve));
  await page.route('**/api/certificates?*', async (route) => { await gate; await route.continue(); });
  await page.goto('http://localhost:3000/#/certificates');
  await page.waitForSelector('[data-testid="list-loading"]');
  console.log('loading state:', (await page.innerText('[data-testid="list-loading"]')).trim(), '| aria-busy =', await page.getAttribute('[data-testid="certificate-list"]', 'aria-busy'));
  await page.screenshot({ path: `${out}/10-loading.png` });
  release();
  await page.waitForSelector('[data-testid="certificate-list"][data-state="success"]');
  await page.unroute('**/api/certificates?*');

  // --- error state: the API becomes unreachable, then recovers
  await page.route('**/api/certificates?*', (route) => route.abort('connectionrefused'));
  await page.fill('[data-testid="search-input"]', 'lee');
  await page.waitForSelector('[data-testid="certificate-list"][data-state="error"]');
  console.log('error state:', (await page.innerText('[data-testid="certificate-list"] .state-error')).replace(/\n+/g, ' / '));
  await page.screenshot({ path: `${out}/11-error.png` });
  await page.unroute('**/api/certificates?*');
  await page.click('[data-testid="certificate-list"] button:has-text("Try again")');
  await page.waitForSelector('[data-testid="certificate-list"][data-state="success"]');
  console.log('after retry rows:', await page.$$eval('[data-testid="certificate-list"] tbody tr', (t) => t.length));
  // server-side error (500) is reported with its status
  await page.route('**/api/certificates?*', (route) => route.fulfill({ status: 500, contentType: 'application/json', body: JSON.stringify({ error: { code: 'internal_error', message: 'Unexpected server error' } }) }));
  await page.fill('[data-testid="search-input"]', 'le');
  await page.waitForSelector('[data-testid="certificate-list"][data-state="error"]');
  console.log('500 state:', (await page.innerText('[data-testid="certificate-list"] .state-error')).replace(/\n+/g, ' / '));
  await page.unroute('**/api/certificates?*');

  // --- bulk issue with a double click
  await page.click('text=Bulk issue');
  await page.waitForSelector('[data-testid="course-select"]');
  await page.screenshot({ path: `${out}/12-bulk-empty.png` });
  await page.selectOption('[data-testid="course-select"]', { label: 'Safety 101' });
  await page.waitForSelector('[data-testid="roster-summary"]');
  console.log('roster summary:', (await page.innerText('[data-testid="roster-summary"]')).replace(/\n+/g, ' '));
  console.log('issue button:', await page.innerText('[data-testid="issue-button"]'));
  await page.screenshot({ path: `${out}/13-bulk-roster.png` });
  // hold the response so the in-flight state is observable, and hammer the button meanwhile
  let releasePost;
  const postGate = new Promise((resolve) => (releasePost = resolve));
  await page.route('**/api/bulk-issues', async (route) => { if (route.request().method() !== 'POST') return route.continue(); await postGate; await route.continue(); });
  await page.dblclick('[data-testid="issue-button"]');
  await page.waitForSelector('[data-testid="operation-status"][data-state="submitting"]');
  for (let i = 0; i < 5; i++) await page.click('[data-testid="issue-button"]', { force: true, timeout: 500 }).catch(() => {});
  await page.evaluate(() => document.querySelector('[data-testid="issue-button"]').click());
  console.log('while submitting: button disabled =', await page.isDisabled('[data-testid="issue-button"]'), '| label =', (await page.innerText('[data-testid="issue-button"]')).trim(), '| status =', (await page.innerText('[data-testid="operation-status"]')).trim().slice(0, 60));
  await page.screenshot({ path: `${out}/14-bulk-submitting.png` });
  releasePost();
  await page.waitForSelector('[data-testid="operation-result"]');
  await page.unroute('**/api/bulk-issues');
  console.log('POST requests sent:', posts.length, posts);
  console.log('summary:', (await page.innerText('[data-testid="operation-summary"]')).replace(/\n+/g, ' '));
  console.log('rows:\n ' + (await page.$$eval('[data-testid="operation-result"] tbody tr', (trs) => trs.map((tr) => [...tr.children].map((td) => td.innerText.trim()).join(' | ')))).join('\n '));
  await page.waitForFunction(() => document.querySelector('[data-testid="eligible-count"]')?.textContent.trim() === '0');
  console.log('after issue: eligible =', await page.innerText('[data-testid="eligible-count"]'), '| button =', await page.innerText('[data-testid="issue-button"]'), '| disabled =', await page.isDisabled('[data-testid="issue-button"]'));
  await page.screenshot({ path: `${out}/15-bulk-result.png`, fullPage: true });

  // --- lost response, then a safe retry with the same key
  posts.length = 0;
  await page.selectOption('[data-testid="course-select"]', { label: 'First Aid Refresher' });
  await page.waitForFunction(() => document.querySelector('[data-testid="eligible-count"]')?.textContent.trim() === '1');
  let dropped = 0;
  await page.route('**/api/bulk-issues', async (route) => {
    if (route.request().method() !== 'POST' || dropped > 0) return route.continue();
    dropped += 1;
    await route.fetch();          // the server executes the operation ...
    await route.abort('failed');  // ... but the answer never reaches the browser
  });
  await page.click('[data-testid="issue-button"]');
  await page.waitForSelector('[data-testid="operation-status"][data-state="failed"]');
  console.log('lost response:', (await page.innerText('[data-testid="operation-status"]')).replace(/\n+/g, ' / '));
  console.log('issue button disabled while outcome unknown:', await page.isDisabled('[data-testid="issue-button"]'));
  await page.screenshot({ path: `${out}/16-bulk-unknown.png` });
  await page.click('[data-testid="retry-button"]');
  await page.waitForSelector('[data-testid="operation-result"]');
  console.log('retry keys identical:', posts.length === 2 && posts[0] === posts[1], posts);
  console.log('replayed note:', !!(await page.$('[data-testid="operation-replayed"]')), '| summary:', (await page.innerText('[data-testid="operation-summary"]')).replace(/\n+/g, ' '));
  await page.waitForSelector('[data-testid="operation-history"]');
  console.log('history:\n ' + (await page.$$eval('[data-testid="operation-history"] tbody tr', (trs) => trs.map((tr) => [...tr.children].slice(0, 7).map((td) => td.innerText.trim()).join(' | ')))).join('\n '));
  await page.screenshot({ path: `${out}/17-bulk-replayed.png`, fullPage: true });

  // --- a rejected request (stale course id) is shown as rejected, without a retry button
  await page.unroute('**/api/bulk-issues');
  console.log('errors:', errors);
  await browser.close();
})().catch((e) => { console.error('FAILED', e); process.exit(1); });

