                  <button type="button" className="btn btn-primary" onClick={() => submit(run.attempt)} data-testid="retry-button">
                    Retry safely
                  </button>
                ) : null}
                <button type="button" className="btn" onClick={() => setRun({ status: 'idle' })}>

