import path from 'node:path';
import { Readable, pipeline } from 'node:stream';

import express from 'express';

import { isBusyError } from './db/sqlite.js';
import { HttpError } from './lib/errors.js';
import { pathId } from './lib/params.js';
import { ACTOR_HEADER, describeActor, listActors, requireActor } from './services/actors.js';
import {
  IDEMPOTENCY_HEADER,
  bulkIssue,
  getBulkOperation,
  listBulkOperations,
  parseIdempotencyKey,
  rejectReusedKeyWithUnreadableBody,
} from './services/bulkIssue.js';
import {
  buildExportPlan,
  exportFileName,
  getCertificate,
  listAuditEvents,
  listCertificates,
  parseListQuery,
  revoke,
  streamCsvExport,
} from './services/certificates.js';
import { getCourseRoster, listCourses } from './services/courses.js';

/**
 * @param {object} deps
 * @param {import('./db/sqlite.js').Connection} deps.db          main connection (all request/response work)
 * @param {() => import('./db/sqlite.js').Connection} deps.openReader  opens a dedicated read-only connection (exports)
 * @param {string|null} [deps.staticDir]   built frontend to serve, if any
 * @param {boolean} [deps.logRequests]
 * @param {() => Date} [deps.now]          clock (tests)
 * @param {object} [deps.hooks]            test seams, see services/bulkIssue.js
 * @param {Pick<Console, 'log' | 'error'>} [deps.logger]
 */
export function createApp({
  db,
  openReader,
  staticDir = null,
  logRequests = false,
  now = () => new Date(),
  hooks = {},
  logger = console,
}) {
  const app = express();
  app.disable('x-powered-by');
  app.set('etag', false);
  app.set('query parser', 'simple');

  if (logRequests) {
    app.use((req, res, next) => {
      if (!req.path.startsWith('/api/')) return next();
      const started = process.hrtime.bigint();
      res.on('finish', () => {
        const ms = Number(process.hrtime.bigint() - started) / 1e6;
        const actor = req.actor ? ` [${req.actor.email}]` : '';
        logger.log(`${req.method} ${req.originalUrl} -> ${res.statusCode} (${ms.toFixed(1)} ms)${actor}`);
      });
      return next();
    });
  }

  const api = express.Router();
  api.use((_req, res, next) => {
    res.set('Cache-Control', 'no-store');
    next();
  });
  api.get('/health', (_req, res) => {
    res.json({ status: 'ok', database: db.driver });
  });

  // Demo-only helper for the actor switcher (there is no login in this console).
  api.get('/actors', (_req, res) => {
    res.json({ header: ACTOR_HEADER, items: listActors(db) });
  });

  // Everything below runs on behalf of an admin and is scoped to that admin's tenant.
  api.use(requireActor(db));

  // Bodies are always JSON; do not make callers fail on a forgotten Content-Type header.
  const jsonBody = express.json({ limit: '100kb', type: () => true });

  // Bulk issue: a body that cannot be read as JSON (malformed, too large, wrong encoding) is still
  // "a different payload" once its Idempotency-Key has been used, so it gets the 409 that key
  // misuse calls for rather than a 400/413. With an unused key the body error is reported as is.
  function bulkIssueBody(req, res, next) {
    jsonBody(req, res, (bodyError) => {
      if (!bodyError) return next();
      try {
        rejectReusedKeyWithUnreadableBody(db, req.actor, parseIdempotencyKey(req.get(IDEMPOTENCY_HEADER)));
      } catch (keyError) {
        // 409 for a reused key. A malformed key (400) is no worse than the unreadable body, which
        // is reported instead; anything else is a genuine failure and must not be papered over.
        if (keyError.status !== 400) return next(keyError);
      }
      return next(bodyError);
    });
  }

  api.get('/me', (req, res) => {
    res.json(describeActor(req.actor));
  });

  api.get('/courses', (req, res) => {
    res.json({ items: listCourses(db, req.actor) });
  });

  api.get('/courses/:courseId/enrollments', (req, res) => {
    res.json(getCourseRoster(db, req.actor, pathId(req.params.courseId), req.query));
  });

  api.get('/certificates', (req, res) => {
    res.json(listCertificates(db, req.actor, parseListQuery(req.query)));
  });

  api.get('/certificates/export.csv', async (req, res) => {
    const plan = buildExportPlan(req.actor, parseListQuery(req.query, { paginate: false }));

    // The export gets its own connection (and with it its own read snapshot), so the long-running
    // download never ties up the connection that serves every other request.
    async function* exportChunks() {
      const reader = openReader();
      try {
        yield* streamCsvExport(reader, plan);
      } finally {
        reader.close();
      }
    }
    const chunks = exportChunks();
    // Pull the first chunk (header + first rows) before committing to a 200: if the export cannot
    // even start, the client still gets a proper JSON error instead of a truncated file.
    const first = await chunks.next();

    res.status(200).set({
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': `attachment; filename="${exportFileName(req.actor, now())}"`,
      'X-Tenant-Timezone': req.actor.timezone,
    });
    const body = Readable.from(
      (async function* withHeader() {
        if (!first.done) yield first.value;
        yield* chunks;
      })(),
      { objectMode: false },
    );
    pipeline(body, res, (err) => {
      // Finalises the generator (closing the snapshot and the connection) however the download ended.
      chunks.return(undefined).catch(() => {});
      if (err && err.code !== 'ERR_STREAM_PREMATURE_CLOSE') logger.error('[export] stream failed:', err);
    });
  });

  api.get('/certificates/:certificateId', (req, res) => {
    res.json(getCertificate(db, req.actor, pathId(req.params.certificateId)));
  });

  api.post('/certificates/:certificateId/revoke', jsonBody, async (req, res) => {
    res.json(await revoke(db, req.actor, pathId(req.params.certificateId), req.body, { now }));
  });

  api.post('/bulk-issues', bulkIssueBody, async (req, res) => {
    const idempotencyKey = parseIdempotencyKey(req.get(IDEMPOTENCY_HEADER));
    const result = await bulkIssue(db, req.actor, { body: req.body, idempotencyKey }, { now, hooks, logger });
    res
      .status(result.status)
      .set({
        'Content-Type': 'application/json; charset=utf-8',
        Location: `/api/bulk-issues/${result.operationId}`,
        'Idempotent-Replayed': String(result.replayed),
      })
      .send(result.body);
  });

  api.get('/bulk-issues', (req, res) => {
    res.json({ items: listBulkOperations(db, req.actor) });
  });

  api.get('/bulk-issues/:operationId', (req, res) => {
    res.type('application/json; charset=utf-8').send(getBulkOperation(db, req.actor, pathId(req.params.operationId)));
  });

  api.get('/audit-events', (req, res) => {
    res.json(listAuditEvents(db, req.actor, req.query));
  });

  api.use((req) => {
    throw new HttpError(404, 'not_found', `No route for ${req.method} ${req.baseUrl}${req.path}`);
  });

  app.use('/api', api);

  // Built single-page frontend (when present). Unknown non-API paths fall back to index.html.
  const indexHtml = staticDir ? path.join(staticDir, 'index.html') : null;
  if (indexHtml && fs.existsSync(indexHtml)) {
    app.use(express.static(staticDir, { index: false, maxAge: '1h' }));
    app.use((req, res, next) => {
      const isPageRequest = (req.method === 'GET' || req.method === 'HEAD') && !path.extname(req.path);
      if (!isPageRequest) return next(); // a missing asset stays a 404 instead of becoming HTML
      res.set('Cache-Control', 'no-cache');
      return res.sendFile(indexHtml);
    });
  } else {
    app.get('/', (_req, res) => {
      res
        .type('text/plain')
        .send('The API is running, but the frontend has not been built yet. Run "npm start" from the repository root.\n');
    });
  }

  // Express identifies error handlers by their four-parameter signature, so `_next` must stay.
  app.use((err, req, res, _next) => {
    if (res.headersSent) {
      // Too late for an error document (streaming response): just drop the connection.
      res.destroy(err);
      return;
    }
    let status = 500;
    let payload = { code: 'internal_error', message: 'Unexpected server error' };

    if (err instanceof HttpError) {
      status = err.status;
      payload = { code: err.code, message: err.message, ...(err.details ? { details: err.details } : {}) };
    } else if (err?.type === 'entity.parse.failed') {
      status = 400;
      payload = { code: 'invalid_json', message: 'Request body is not valid JSON' };
    } else if (err?.type === 'entity.too.large') {
      status = 413;
      payload = { code: 'payload_too_large', message: 'Request body is too large' };
    } else if (isBusyError(err)) {
      status = 503;
      res.set('Retry-After', '1');
      payload = { code: 'database_busy', message: 'The database is busy; retry the request shortly' };
    } else if (Number.isInteger(err?.status) && err.status >= 400 && err.status < 500) {
      status = err.status;
      payload = { code: 'invalid_request', message: err.expose ? err.message : 'Invalid request' };
    } else {
      logger.error(`[error] ${req.method} ${req.originalUrl}:`, err);
    }
    res.status(status).json({ error: payload });
  });

  return app;
}

/**
 * Database schema.
 *
 * Tenant isolation is enforced twice: every query in the service layer is scoped by the actor's
 * tenant, and the schema itself refuses cross-tenant rows - every reference between tenant-owned
 * tables is a composite `(id, tenant_id)` foreign key, so a certificate in one tenant can never
 * point at a course, learner, enrollment, admin or bulk operation of another, and an audit event
 * can never point at another tenant's certificate.
 */

/** Bump whenever SCHEMA_SQL changes; a database file from another version is refused at start-up. */
export const SCHEMA_VERSION = 2;

const SCHEMA_SQL = `
CREATE TABLE tenants (
  id          INTEGER PRIMARY KEY,
  name        TEXT    NOT NULL UNIQUE,
  code        TEXT    NOT NULL UNIQUE,            -- serial-number prefix, e.g. EAST
  timezone    TEXT    NOT NULL,                   -- IANA zone, e.g. Australia/Sydney
  last_serial INTEGER NOT NULL DEFAULT 0,         -- per-tenant serial counter
  created_at  TEXT    NOT NULL
) STRICT;

CREATE TABLE admins (
  id           INTEGER PRIMARY KEY,
  tenant_id    INTEGER NOT NULL REFERENCES tenants (id),
  email        TEXT    NOT NULL UNIQUE COLLATE NOCASE,
  display_name TEXT    NOT NULL,
  created_at   TEXT    NOT NULL,
  UNIQUE (id, tenant_id)
) STRICT;

CREATE TABLE courses (
  id           INTEGER PRIMARY KEY,
  tenant_id    INTEGER NOT NULL REFERENCES tenants (id),
  title        TEXT    NOT NULL CHECK (length(trim(title)) > 0),
  is_generated INTEGER NOT NULL DEFAULT 0 CHECK (is_generated IN (0, 1)),  -- 1 = load-test data
  created_at   TEXT    NOT NULL,
  UNIQUE (tenant_id, title),
  UNIQUE (id, tenant_id)
) STRICT;

CREATE TABLE learners (
  id           INTEGER PRIMARY KEY,
  tenant_id    INTEGER NOT NULL REFERENCES tenants (id),
  full_name    TEXT    NOT NULL,
  email        TEXT,
  is_generated INTEGER NOT NULL DEFAULT 0 CHECK (is_generated IN (0, 1)),
  created_at   TEXT    NOT NULL,
  UNIQUE (id, tenant_id)
) STRICT;
CREATE INDEX idx_learners_tenant ON learners (tenant_id, is_generated);

CREATE TABLE enrollments (
  id           INTEGER PRIMARY KEY,
  tenant_id    INTEGER NOT NULL,
  course_id    INTEGER NOT NULL,
  learner_id   INTEGER NOT NULL,
  status       TEXT    NOT NULL CHECK (status IN ('not_started', 'in_progress', 'completed')),
  completed_at TEXT,
  created_at   TEXT    NOT NULL,
  UNIQUE (tenant_id, course_id, learner_id),
  UNIQUE (id, tenant_id),
  CHECK ((status = 'completed') = (completed_at IS NOT NULL)),
  FOREIGN KEY (course_id, tenant_id)  REFERENCES courses (id, tenant_id),
  FOREIGN KEY (learner_id, tenant_id) REFERENCES learners (id, tenant_id)
) STRICT;
CREATE INDEX idx_enrollments_learner ON enrollments (learner_id);

-- One row per bulk-issue request that actually executed. It doubles as the idempotency record:
-- response_body is replayed verbatim to every retry that carries the same key and payload.
CREATE TABLE bulk_issue_operations (
  id               INTEGER PRIMARY KEY,
  tenant_id        INTEGER NOT NULL,
  actor_admin_id   INTEGER NOT NULL,
  course_id        INTEGER NOT NULL,
  idempotency_key  TEXT,
  request_hash     TEXT    NOT NULL,
  status           TEXT    NOT NULL CHECK (status IN ('running', 'completed')),
  issued_count     INTEGER NOT NULL DEFAULT 0,
  skipped_count    INTEGER NOT NULL DEFAULT 0,
  failed_count     INTEGER NOT NULL DEFAULT 0,
  response_status  INTEGER,
  response_body    TEXT,
  created_at       TEXT    NOT NULL,
  completed_at     TEXT,
  UNIQUE (id, tenant_id),
  FOREIGN KEY (actor_admin_id, tenant_id) REFERENCES admins (id, tenant_id),
  FOREIGN KEY (course_id, tenant_id)      REFERENCES courses (id, tenant_id)
) STRICT;
CREATE UNIQUE INDEX idx_bulk_ops_idempotency
  ON bulk_issue_operations (tenant_id, actor_admin_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;
CREATE INDEX idx_bulk_ops_tenant ON bulk_issue_operations (tenant_id, id);
CREATE INDEX idx_bulk_ops_course ON bulk_issue_operations (course_id);

CREATE TABLE certificates (
  id                  INTEGER PRIMARY KEY,
  tenant_id           INTEGER NOT NULL,
  course_id           INTEGER NOT NULL,
  learner_id          INTEGER NOT NULL,
  enrollment_id       INTEGER,
  serial_number       TEXT    NOT NULL UNIQUE,
  -- Names are snapshotted: a certificate is an issued document and must not change when the
  -- learner or course is renamed. It also keeps list/search/export free of joins.
  learner_name        TEXT    NOT NULL CHECK (length(trim(learner_name)) > 0),
  course_title        TEXT    NOT NULL CHECK (length(trim(course_title)) > 0),
  status              TEXT    NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  issued_at           TEXT    NOT NULL,           -- UTC instant, ISO-8601 (source of truth)
  -- Calendar date of issued_at in the tenant's time zone, materialised at issue time so that
  -- "sort by issue date" is index-backed and follows the tenant-local calendar, not UTC.
  issued_local_date   TEXT    NOT NULL CHECK (issued_local_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  issued_by_admin_id  INTEGER,
  bulk_operation_id   INTEGER,
  revoked_at          TEXT,
  revoked_by_admin_id INTEGER,
  revocation_reason   TEXT,
  -- At most one certificate per learner per course, ever. This is the last line of defence
  -- against double issuance, whatever the application layer does.
  UNIQUE (tenant_id, course_id, learner_id),
  UNIQUE (id, tenant_id),
  CHECK ((status = 'revoked') = (revoked_at IS NOT NULL)),
  FOREIGN KEY (course_id, tenant_id)           REFERENCES courses (id, tenant_id),
  FOREIGN KEY (learner_id, tenant_id)          REFERENCES learners (id, tenant_id),
  FOREIGN KEY (enrollment_id, tenant_id)       REFERENCES enrollments (id, tenant_id),
  FOREIGN KEY (issued_by_admin_id, tenant_id)  REFERENCES admins (id, tenant_id),
  FOREIGN KEY (bulk_operation_id, tenant_id)   REFERENCES bulk_issue_operations (id, tenant_id),
  FOREIGN KEY (revoked_by_admin_id, tenant_id) REFERENCES admins (id, tenant_id)
) STRICT;
-- One index per sort order, each ending in id: the deterministic tie-breaker for equal sort keys.
CREATE INDEX idx_certificates_issued  ON certificates (tenant_id, issued_local_date, issued_at, id);
CREATE INDEX idx_certificates_learner ON certificates (tenant_id, learner_name COLLATE NOCASE, id);
CREATE INDEX idx_certificates_course  ON certificates (tenant_id, course_title COLLATE NOCASE, id);
CREATE INDEX idx_certificates_serial  ON certificates (tenant_id, serial_number, id);
CREATE INDEX idx_certificates_status  ON certificates (tenant_id, status, id);
CREATE INDEX idx_certificates_learner_id ON certificates (learner_id);
CREATE INDEX idx_certificates_enrollment ON certificates (enrollment_id);
CREATE INDEX idx_certificates_bulk_op ON certificates (bulk_operation_id) WHERE bulk_operation_id IS NOT NULL;

-- Append-only audit trail. Exactly one row per certificate issuance and per effective revocation.
CREATE TABLE audit_events (
  id                INTEGER PRIMARY KEY,
  tenant_id         INTEGER NOT NULL REFERENCES tenants (id),
  actor_admin_id    INTEGER,
  actor_email       TEXT    NOT NULL,
  action            TEXT    NOT NULL CHECK (action IN ('certificate.issued', 'certificate.revoked')),
  certificate_id    INTEGER NOT NULL,
  bulk_operation_id INTEGER,
  details           TEXT    NOT NULL DEFAULT '{}',
  created_at        TEXT    NOT NULL,
  FOREIGN KEY (actor_admin_id, tenant_id)    REFERENCES admins (id, tenant_id),
  FOREIGN KEY (certificate_id, tenant_id)    REFERENCES certificates (id, tenant_id),
  FOREIGN KEY (bulk_operation_id, tenant_id) REFERENCES bulk_issue_operations (id, tenant_id)
) STRICT;
CREATE INDEX idx_audit_tenant      ON audit_events (tenant_id, id);
CREATE INDEX idx_audit_certificate ON audit_events (certificate_id, id);
CREATE INDEX idx_audit_bulk_op     ON audit_events (bulk_operation_id) WHERE bulk_operation_id IS NOT NULL;
`;

const readVersion = (db) => db.get('PRAGMA user_version').user_version;

/** Creates the schema on an empty database; a no-op when it is already at the current version. */
export function migrate(db) {
  if (readVersion(db) === SCHEMA_VERSION) return;
  db.transaction(() => {
    // Look again now that the write lock is held: another process starting at the same moment
    // may have created the schema while this one was waiting.
    const version = readVersion(db);
    if (version === SCHEMA_VERSION) return;
    if (version !== 0) {
      throw new Error(
        `Database schema version ${version} is not supported by this build (expected ${SCHEMA_VERSION}). ` +
          'Stop the server and run "npm run db:reset" to recreate the demo database.',
      );
    }
    db.exec(SCHEMA_SQL);
    db.exec(`PRAGMA user_version = ${SCHEMA_VERSION}`);
  });
}

/**
 * Bulk issue: one certificate for every eligible learner of a course, with per-learner outcomes.
 *
 * Retry safety
 * ------------
 * The whole operation - idempotency lookup, eligibility check, certificates, audit events and the
 * stored response - is ONE `BEGIN IMMEDIATE` transaction. SQLite admits a single writer at a time,
 * so identical requests racing each other (in this process or in another one sharing the file) are
 * strictly serialised: the first one executes and commits its response next to the idempotency
 * key, every later one finds that row and replays the stored response byte for byte. There is no
 * observable "in progress" state and therefore no window in which a duplicate could slip through.
 *
 * A crash before COMMIT leaves nothing behind (no certificates, no audit events, no key), so the
 * client's retry simply runs the operation for the first time.
 *
 * Independently of idempotency keys, UNIQUE (tenant_id, course_id, learner_id) on certificates
 * makes a second certificate for the same learner and course impossible.
 */
import { HttpError, badRequest, notFound } from '../lib/errors.js';
import { requestFingerprint } from '../lib/fingerprint.js';
import { pathId } from '../lib/params.js';
import { localDateTime } from '../lib/time.js';
import { TransactionAbortedError } from '../db/sqlite.js';
import { classifyEnrollment, findCourse, loadRoster } from './courses.js';
import { issueCertificate } from './ledger.js';

export const IDEMPOTENCY_HEADER = 'Idempotency-Key';
const ROUTE = '/api/bulk-issues';
const IDEMPOTENCY_KEY_PATTERN = /^[\x21-\x7E]{1,200}$/;

export function parseIdempotencyKey(headerValue) {
  if (headerValue === undefined) return null;
  const key = String(headerValue).trim();
  if (!IDEMPOTENCY_KEY_PATTERN.test(key)) {
    throw badRequest(`${IDEMPOTENCY_HEADER} must be 1-200 printable ASCII characters without spaces`);
  }
  return key;
}

function parseCourseId(body) {
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    throw badRequest('Request body must be a JSON object such as {"courseId": 1}');
  }
  const value = body.courseId ?? body.course_id;
  const courseId = Number.isSafeInteger(value) && value > 0 ? value : pathId(typeof value === 'string' ? value : '');
  if (courseId === null) throw badRequest('"courseId" is required and must be a positive integer');
  return courseId;
}

function failureMessage(err) {
  const text = String(err?.message ?? err).replace(/\s+/g, ' ').trim();
  return `Certificate could not be issued: ${text.slice(0, 200) || 'unexpected error'}`;
}

/**
 * What an earlier request with this key left behind, if anything: its stored response when the
 * payload is the same, a 409 when it is not. Keys are scoped to (tenant, admin), so one actor can
 * never replay - or collide with - another actor's operation, let alone another tenant's.
 * `requestHash` null means "this request has no readable payload", which can only be a mismatch.
 */
function answerFromStoredKey(db, actor, idempotencyKey, requestHash) {
  if (idempotencyKey === null) return null;
  const previous = db.get(
    `SELECT id, request_hash, response_status, response_body
       FROM bulk_issue_operations
      WHERE tenant_id = @tenantId AND actor_admin_id = @adminId AND idempotency_key = @idempotencyKey`,
    { tenantId: actor.tenantId, adminId: actor.adminId, idempotencyKey },
  );
  if (!previous) return null;
  if (previous.request_hash !== requestHash) {
    throw new HttpError(
      409,
      'idempotency_key_reused',
      `${IDEMPOTENCY_HEADER} "${idempotencyKey}" was already used for a different request. ` +
        'Retry with the original payload, or use a new key for a new operation.',
      { operationId: previous.id },
    );
  }
  return { status: previous.response_status, body: previous.response_body, replayed: true, operationId: previous.id };
}

/**
 * For requests whose body could not even be parsed: if the key has already been used, this is a
 * reuse with a different payload (409); otherwise the caller reports the body error itself.
 */
export function rejectReusedKeyWithUnreadableBody(db, actor, idempotencyKey) {
  answerFromStoredKey(db, actor, idempotencyKey, null);
}

/**
 * Executes (or replays) a bulk issue.
 *
 * @returns {Promise<{ status: number, body: string, replayed: boolean, operationId: number }>}
 *   `body` is the JSON text of the operation; replays return the stored text unchanged.
 */
export async function bulkIssue(db, actor, { body, idempotencyKey }, { now = () => new Date(), hooks = {}, logger = console } = {}) {
  const requestHash = requestFingerprint('POST', ROUTE, body);

  // Fast path: a key that already ran is answered from a plain read (replay or 409). It needs no
  // write lock, so retries are served even while another process is in the middle of a long write.
  const stored = answerFromStoredKey(db, actor, idempotencyKey, requestHash);
  if (stored) return stored;

  // Obviously invalid requests are turned away before queueing for the write lock as well.
  if (!findCourse(db, actor, parseCourseId(body))) throw notFound('Course');

  return db.writeTransaction(() => {
    // 1. The decisive idempotency check, now under the write lock: an identical request that was
    //    racing this one has either not started (we execute) or has committed (we replay).
    const raced = answerFromStoredKey(db, actor, idempotencyKey, requestHash);
    if (raced) return raced;

    // 2. Validation. Nothing has been written yet, so a rejected request leaves no trace: no
    //    operation row, no idempotency record, no certificates, no audit events.
    const courseId = parseCourseId(body);
    const course = findCourse(db, actor, courseId);
    if (!course) throw notFound('Course'); // also the answer for another tenant's course

    // 3. Execute.
    const startedAt = now().toISOString();
    const tenant = { id: actor.tenantId, code: actor.tenantCode, timezone: actor.timezone };
    const operationId = db.run(
      `INSERT INTO bulk_issue_operations (tenant_id, actor_admin_id, course_id, idempotency_key, request_hash, status, created_at)
       VALUES (@tenantId, @adminId, @courseId, @idempotencyKey, @requestHash, 'running', @createdAt)`,
      {
        tenantId: actor.tenantId,
        adminId: actor.adminId,
        courseId: course.id,
        idempotencyKey,
        requestHash,
        createdAt: startedAt,
      },
    ).lastInsertRowid;

    const results = [];
    const summary = { total: 0, issued: 0, skipped: 0, failed: 0 };

    for (const row of loadRoster(db, actor.tenantId, course.id)) {
      const base = { learnerId: row.learner_id, learnerName: row.learner_name, enrollmentId: row.enrollment_id };
      const verdict = classifyEnrollment(row);
      summary.total += 1;

      if (!verdict.eligible) {
        summary.skipped += 1;
        const skipped = { ...base, outcome: 'skipped', reason: verdict.reason, message: verdict.message };
        if (row.certificate_id !== null) {
          skipped.certificateId = row.certificate_id;
          skipped.serialNumber = row.serial_number;
        }
        results.push(skipped);
        continue;
      }

      try {
        // Each learner gets a SAVEPOINT: if issuing fails for one of them, only that learner's
        // partial writes are undone and reported as "failed"; everyone else is unaffected.
        const certificate = db.transaction(() => {
          const learner = { id: row.learner_id, name: row.learner_name };
          hooks.beforeIssue?.({ learner, course, tenant });
          return issueCertificate(db, {
            tenant,
            actor,
            course,
            learner,
            enrollmentId: row.enrollment_id,
            issuedAt: startedAt,
            bulkOperationId: operationId,
            auditDetails: { enrollmentId: row.enrollment_id, idempotencyKey },
          });
        });
        summary.issued += 1;
        results.push({
          ...base,
          outcome: 'issued',
          certificateId: certificate.id,
          serialNumber: certificate.serialNumber,
          issuedAt: certificate.issuedAt,
          issuedLocal: localDateTime(certificate.issuedAt, actor.timezone),
        });
      } catch (err) {
        if (err instanceof TransactionAbortedError) throw err; // nothing can be salvaged; fail the request
        logger.error(`[bulk-issue] operation ${operationId}: learner ${row.learner_id} failed:`, err);
        summary.failed += 1;
        results.push({ ...base, outcome: 'failed', reason: 'issue_failed', message: failureMessage(err) });
      }
    }

    // 4. Store the response with the operation so every retry gets the identical answer.
    const status = 201;
    const completedAt = now().toISOString();
    const responseBody = JSON.stringify({
      id: operationId,
      status: 'completed',
      course,
      idempotencyKey,
      requestedBy: actor.email,
      tenant: { name: actor.tenantName, timezone: actor.timezone },
      createdAt: startedAt,
      completedAt,
      summary,
      results,
    });
    db.run(
      `UPDATE bulk_issue_operations
          SET status = 'completed', issued_count = @issued, skipped_count = @skipped, failed_count = @failed,
              response_status = @status, response_body = @body, completed_at = @completedAt
        WHERE id = @operationId`,
      {
        issued: summary.issued,
        skipped: summary.skipped,
        failed: summary.failed,
        status,
        body: responseBody,
        completedAt,
        operationId,
      },
    );

    return { status, body: responseBody, replayed: false, operationId };
  });
}

/** Stored result of a past operation (same JSON that the POST returned). 404 across tenants. */
export function getBulkOperation(db, actor, operationId) {
  const row =
    operationId === null
      ? undefined
      : db.get(
          `SELECT response_body FROM bulk_issue_operations
            WHERE id = @operationId AND tenant_id = @tenantId AND status = 'completed'`,
          { operationId, tenantId: actor.tenantId },
        );
  if (!row) throw notFound('Bulk issue operation');
  return row.response_body;
}

/** Most recent operations of the tenant, without the per-learner detail. */
export function listBulkOperations(db, actor, { limit = 10 } = {}) {
  return db
    .all(
      `SELECT o.id, o.course_id, c.title AS course_title, o.idempotency_key, o.issued_count, o.skipped_count,
              o.failed_count, o.created_at, a.email AS requested_by
         FROM bulk_issue_operations o
         JOIN courses c ON c.id = o.course_id
         JOIN admins a ON a.id = o.actor_admin_id
        WHERE o.tenant_id = @tenantId AND o.status = 'completed'
        ORDER BY o.id DESC
        LIMIT @limit`,
      { tenantId: actor.tenantId, limit },
    )
    .map((row) => ({
      id: row.id,
      status: 'completed',
      course: { id: row.course_id, title: row.course_title },
      idempotencyKey: row.idempotency_key,
      requestedBy: row.requested_by,
      createdAt: row.created_at,
      createdLocal: localDateTime(row.created_at, actor.timezone),
      summary: {
        total: row.issued_count + row.skipped_count + row.failed_count,
        issued: row.issued_count,
        skipped: row.skipped_count,
        failed: row.failed_count,
      },
    }));
}

