1	/**
2	 * Certificate queries: list, detail, revocation and the streaming CSV export.
3	 *
4	 * The list endpoint and the export share one filter + ordering builder, so an export always
5	 * contains exactly the rows (and the order) the admin is looking at.
6	 */
7	import { setImmediate as yieldToEventLoop } from 'node:timers/promises';
8	
9	import { csvRow } from '../lib/csv.js';
10	import { badRequest, notFound } from '../lib/errors.js';
11	import { assertPlainText, queryInteger, queryString } from '../lib/params.js';
12	import { createLocalDateTimeFormatter, localDateTime, utcOffset } from '../lib/time.js';
13	import { revokeCertificate } from './ledger.js';
14	
15	export const DEFAULT_PAGE_SIZE = 25;
16	export const MAX_PAGE_SIZE = 100;
17	const MAX_REASON_LENGTH = 500;
18	
19	/**
20	 * Sort keys. Every ordering ends in `id`, so rows with equal sort values always come back in the
21	 * same order - pagination never skips or repeats a row and two exports of the same data are
22	 * byte-identical.
23	 *
24	 * "issued" sorts by the tenant-local calendar date first (not the UTC date), then by the exact
25	 * instant so a single day reads chronologically, then by id.
26	 */
27	const SORTS = {
28	  issued: (dir) => `c.issued_local_date ${dir}, c.issued_at ${dir}, c.id ${dir}`,
29	  learner: (dir) => `c.learner_name COLLATE NOCASE ${dir}, c.id ${dir}`,
30	  course: (dir) => `c.course_title COLLATE NOCASE ${dir}, c.id ${dir}`,
31	  serial: (dir) => `c.serial_number ${dir}, c.id ${dir}`,
32	  status: (dir) => `c.status ${dir}, c.id ${dir}`,
33	};
34	
35	/**
36	 * The index that already stores each ordering. List and export name it explicitly (INDEXED BY),
37	 * so SQLite always walks the index in order - it can stop after one page, and an export starts
38	 * streaming immediately instead of first sorting the whole tenant, whatever the planner statistics say.
39	 */
40	const SORT_INDEXES = {
41	  issued: 'idx_certificates_issued',
42	  learner: 'idx_certificates_learner',
43	  course: 'idx_certificates_course',
44	  serial: 'idx_certificates_serial',
45	  status: 'idx_certificates_status',
46	};
47	
48	const SORT_ALIASES = {
49	  issued: 'issued',
50	  issuedat: 'issued',
51	  issuedate: 'issued',
52	  issueddate: 'issued',
53	  issuedlocal: 'issued',
54	  issuedlocaldate: 'issued',
55	  date: 'issued',
56	  learner: 'learner',
57	  learnername: 'learner',
58	  name: 'learner',
59	  course: 'course',
60	  coursetitle: 'course',
61	  serial: 'serial',
62	  serialnumber: 'serial',
63	  status: 'status',
64	};
65	
66	const DEFAULT_ORDER = { issued: 'desc', learner: 'asc', course: 'asc', serial: 'asc', status: 'asc' };
67	const STATUSES = ['all', 'active', 'revoked'];
68	
69	/** Validates list/export query parameters. Unknown values are rejected rather than silently ignored. */
70	export function parseListQuery(query, { paginate = true } = {}) {
71	  const q = queryString(query, ['q', 'search'], { maxLength: 100 }) ?? '';
72	
73	  const status = (queryString(query, ['status']) ?? 'all').toLowerCase() || 'all';
74	  if (!STATUSES.includes(status)) throw badRequest(`"status" must be one of: ${STATUSES.join(', ')}`);
75	
76	  let sortText = (queryString(query, ['sort', 'sortBy']) || 'issued').toLowerCase();
77	  let order = queryString(query, ['order', 'dir', 'direction', 'sortOrder'])?.toLowerCase();
78	  if (sortText.startsWith('-')) {
79	    sortText = sortText.slice(1);
80	    order ??= 'desc';
81	  }
82	  // Object.hasOwn: a plain object also "has" constructor, toString, ... through its prototype.
83	  const sortKey = sortText.replace(/[^a-z]/g, '');
84	  const sort = Object.hasOwn(SORT_ALIASES, sortKey) ? SORT_ALIASES[sortKey] : undefined;
85	  if (!sort) throw badRequest(`"sort" must be one of: ${Object.keys(SORTS).join(', ')}`);
