98	export function generateCertificates(db, { tenantName, count = 100_000, seed = 20260110 }) {
99	  if (!Number.isInteger(count) || count < 1 || count > 2_000_000) {
100	    throw new Error('count must be an integer between 1 and 2,000,000');
101	  }
