128	        ).lastInsertRowid,
129	      };
130	    }
131	
132	    // Issue instants: sorted batch timestamps, each shared by ~25 certificates -----------------
133	    const batchCount = Math.max(1, Math.round(count / CERTIFICATES_PER_BATCH));
134	    const batchInstants = new Float64Array(batchCount);
135	    for (let b = 0; b < batchCount; b += 1) {
136	      batchInstants[b] = WINDOW_START + Math.floor((random() * (WINDOW_END - WINDOW_START)) / 1000) * 1000;
137	    }
138	    batchInstants.sort();
139	
140	    // Visit every (learner, course) pair exactly once, in a scrambled but reproducible order.
141	    let stride = 7919;
142	    while (gcd(stride, count) !== 1) stride += 2;
143	
144	    const firstSerial = reserveSerials(db, tenant.id, count);
145	    let revokedCount = 0;
146	    let previousBatch = -1;
147	    let issuedAt = '';
148	    let issuedLocalDate = '';
149	
150	    // Rows are inserted in chronological order, so ids and serial numbers follow the timeline.
151	    for (let k = 0; k < count; k += 1) {
152	      const batch = Math.min(batchCount - 1, Math.floor((k * batchCount) / count));
153	      if (batch !== previousBatch) {
154	        previousBatch = batch;
155	        issuedAt = new Date(batchInstants[batch]).toISOString();
156	        issuedLocalDate = localDate(issuedAt, tenant.timezone);
157	      }
158	      const pair = (k * stride) % count;
159	      const learner = learners[Math.floor(pair / courses.length)];
160	      const course = courses[pair % courses.length];
161	      const serialNumber = formatSerial(tenant.code, firstSerial + k);
162	
163	      const enrollmentId = db.run(
164	        `INSERT INTO enrollments (tenant_id, course_id, learner_id, status, completed_at, created_at)
165	         VALUES (@tenantId, @courseId, @learnerId, 'completed', @completedAt, @createdAt)`,
166	        {
167	          tenantId: tenant.id,
168	          courseId: course.id,
169	          learnerId: learner.id,
170	          completedAt: new Date(batchInstants[batch] - Math.ceil(random() * 72) * HOUR).toISOString(),
171	          createdAt,
172	        },
173	      ).lastInsertRowid;
174	
175	      const revokedAt =
176	        random() < REVOKED_SHARE ? new Date(batchInstants[batch] + Math.ceil(random() * 20) * DAY).toISOString() : null;
177	      const reason = revokedAt ? 'Generated revocation (load test)' : null;
178	
179	      const certificateId = db.run(
180	        `INSERT INTO certificates (tenant_id, course_id, learner_id, enrollment_id, serial_number, learner_name, course_title,
181	                                   status, issued_at, issued_local_date, issued_by_admin_id,
182	                                   revoked_at, revoked_by_admin_id, revocation_reason)
183	         VALUES (@tenantId, @courseId, @learnerId, @enrollmentId, @serialNumber, @learnerName, @courseTitle,
184	                 @status, @issuedAt, @issuedLocalDate, @adminId,
185	                 @revokedAt, @revokedBy, @reason)`,
186	        {
187	          tenantId: tenant.id,
188	          courseId: course.id,
189	          learnerId: learner.id,
190	          enrollmentId,
191	          serialNumber,
192	          learnerName: learner.name,
193	          courseTitle: course.title,
194	          status: revokedAt ? 'revoked' : 'active',
195	          issuedAt,
196	          issuedLocalDate,
197	          adminId: admin.id,
198	          revokedAt,
199	          revokedBy: revokedAt ? admin.id : null,
200	          reason,
201	        },
202	      ).lastInsertRowid;
203	
204	      const audit = (action, at, details) =>
205	        db.run(
206	          `INSERT INTO audit_events (tenant_id, actor_admin_id, actor_email, action, certificate_id, details, created_at)
207	           VALUES (@tenantId, @adminId, @email, @action, @certificateId, @details, @createdAt)`,
208	          {
209	            tenantId: tenant.id,
210	            adminId: admin.id,
211	            email: admin.email,
212	            action,
213	            certificateId,
214	            details: JSON.stringify(details),
215	            createdAt: at,
216	          },
217	        );
218	      audit(AUDIT_ACTIONS.ISSUED, issuedAt, {
219	        serialNumber,
220	        learnerId: learner.id,
221	        learnerName: learner.name,
222	        courseId: course.id,
223	        courseTitle: course.title,
224	        source: 'load-test-generator',
225	      });
226	      if (revokedAt) {
227	        revokedCount += 1;
228	        audit(AUDIT_ACTIONS.REVOKED, revokedAt, { serialNumber, reason, previousStatus: 'active', source: 'load-test-generator' });
229	      }
230	    }
231	
232	    return {
233	      tenant: tenant.name,
234	      generated: count,
235	      replaced,
236	      revoked: revokedCount,
237	      courses: courses.length,
238	      learners: learnerCount,
239	      distinctIssueInstants: batchCount,
240	      totalCertificatesInTenant: db.get('SELECT COUNT(*) AS n FROM certificates WHERE tenant_id = @tenantId', {
241	        tenantId: tenant.id,
242	      }).n,
243	    };
244	  });
245	}
