     1	#!/usr/bin/env node
     2	/**
     3	 * Database initialisation CLI.
     4	 *
     5	 *   node scripts/init-db.js           # create schema + demo data if the database is empty
     6	 *   node scripts/init-db.js --reset   # restore the pristine quick-start dataset
     7	 *
     8	 * `--reset` empties and re-seeds the tables inside one transaction; it never deletes the file of
     9	 * a usable database, so a server that has it open simply sees the fresh data afterwards. If
    10	 * another process is in the middle of a long write, the reset gives up without changing anything.
    11	 */
    12	import fs from 'node:fs';
    13	import { parseArgs } from 'node:util';
    14	
    15	import { openInitializedDatabase } from '../src/bootstrap.js';
    16	import { loadConfig, resolveUserPath } from '../src/config.js';
    17	import { SCHEMA_VERSION } from '../src/db/schema.js';
    18	import { seedDemoData } from '../src/db/seed.js';
    19	import { isBusyError, openDatabase, removeDatabaseFiles } from '../src/db/sqlite.js';
    20	
    21	const { values } = parseArgs({
    22	  options: { reset: { type: 'boolean', default: false }, db: { type: 'string' } },
    23	});
    24	
    25	const dbPath = values.db ? resolveUserPath(values.db) : loadConfig().dbPath;
    26	
    27	// Children before parents, so foreign keys stay satisfied at every step.
    28	const TABLES_IN_DELETE_ORDER = [
    29	  'audit_events',
    30	  'certificates',
    31	  'bulk_issue_operations',
    32	  'enrollments',
    33	  'learners',
    34	  'courses',
    35	  'admins',
    36	  'tenants',
    37	];
    38	
    39	/** Returns 'done', 'empty' (nothing to reset yet) or 'incompatible' (file from another schema version). */
    40	function resetInPlace() {
    41	  const db = openDatabase(dbPath);
    42	  try {
    43	    const { user_version: version } = db.get('PRAGMA user_version');
    44	    if (version === 0) return 'empty';
    45	    if (version !== SCHEMA_VERSION) return 'incompatible';
    46	    db.transaction(() => {
    47	      for (const table of TABLES_IN_DELETE_ORDER) db.exec(`DELETE FROM ${table}`);
    48	      seedDemoData(db);
    49	    });
    50	    try {
    51	      // Hand the space of removed load-test rows back to the file system: rebuild the file, then
    52	      // fold the write-ahead log into it (which is what actually shrinks both files on disk).
    53	      db.exec('VACUUM');
    54	      db.exec('PRAGMA busy_timeout = 1000');
