     1	/** RFC 4180 style CSV encoding with spreadsheet formula-injection hardening. */
     2	
     3	const NEEDS_QUOTING = /[",\r\n]/;
     4	const FORMULA_TRIGGER = /^[=+\-@\t\r]/;
     5	
     6	export function csvCell(value) {
     7	  let text = value === null || value === undefined ? '' : String(value);
     8	  // A cell that starts with = + - @ is executed as a formula by Excel/Sheets. Learner names are
     9	  // user-controlled, so neutralise those with a leading apostrophe (OWASP CSV-injection guidance).
    10	  if (FORMULA_TRIGGER.test(text)) text = `'${text}`;
    11	  return NEEDS_QUOTING.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
    12	}
    13	
    14	export function csvRow(cells) {
    15	  let line = '';
    16	  for (let i = 0; i < cells.length; i += 1) {
    17	    if (i > 0) line += ',';
    18	    line += csvCell(cells[i]);
    19	  }
    20	  return `${line}\n`;
