26	export function createTempDir(prefix = 'cert-admin-test-') {
27	  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
28	}
29	
30	export function removeTempDir(dir) {
31	  fs.rmSync(dir, { recursive: true, force: true });
32	}
33	
34	/**
35	 * Runs a node entry point of the backend to completion: `{ code, output }` (stdout + stderr).
36	 * A process that is still running after `timeoutMs` is killed and reported with `code: null`.
37	 */
38	function runNodeToExit(args, { env = {}, timeoutMs = 180_000 } = {}) {
39	  return new Promise((resolve, reject) => {
40	    const child = spawn(process.execPath, args, {
41	      cwd: BACKEND_DIR,
42	      env: { ...process.env, ...env },
43	      stdio: ['ignore', 'pipe', 'pipe'],
44	    });
45	    let output = '';
46	    const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
47	    child.stdout.on('data', (chunk) => (output += chunk));
48	    child.stderr.on('data', (chunk) => (output += chunk));
49	    child.on('error', (err) => {
50	      clearTimeout(timer);
51	      reject(err);
52	    });
53	    child.on('close', (code) => {
54	      clearTimeout(timer);
55	      resolve({ code, output });
56	    });
57	  });
58	}
59	
60	/** Runs a CLI script from backend/scripts and resolves with its combined output; rejects on a non-zero exit. */
61	export async function runScript(script, args = [], options) {
62	  const { code, output } = await runScriptToExit(script, args, options);
63	  if (code !== 0) throw new Error(`node scripts/${script} ${args.join(' ')} exited with code ${code}\n${output}`);
64	  return output;
65	}
66	
67	/** Like `runScript`, for scripts that are expected to fail: resolves with `{ code, output }`. */
68	export function runScriptToExit(script, args = [], options) {
69	  return runNodeToExit([path.join('scripts', script), ...args], options);
70	}
71	
72	const serverEnv = (dbPath, env) => ({
73	  PORT: '0',
74	  DB_PATH: dbPath,
75	  LOG_REQUESTS: '0',
76	  STATIC_DIR: path.join(BACKEND_DIR, 'no-frontend'),
77	  ...env,
78	});
79	
80	/** For start-ups that are expected to fail: runs `src/server.js` until it exits, `{ code, output }`. */
81	export function runServerToExit(dbPath, { env = {} } = {}) {
82	  return runNodeToExit([path.join('src', 'server.js')], { env: serverEnv(dbPath, env), timeoutMs: 20_000 });
83	}
84	
85	/** Starts `src/server.js` on a free port and resolves once it accepts requests. */
86	export function startServer(dbPath, { env = {} } = {}) {
87	  return new Promise((resolve, reject) => {
88	    const child = spawn(process.execPath, [path.join('src', 'server.js')], {
89	      cwd: BACKEND_DIR,
90	      env: { ...process.env, ...serverEnv(dbPath, env) },
91	      stdio: ['ignore', 'pipe', 'pipe'],
92	    });
93	    let output = '';
94	    let settled = false;
95	    const timer = setTimeout(() => fail(new Error(`Server did not start in time:\n${output}`)), 20_000);
96	
97	    function fail(err) {
98	      if (settled) return;
99	      settled = true;
100	      clearTimeout(timer);
101	      child.kill('SIGKILL');
102	      reject(err);
103	    }
104	    function onData(chunk) {
105	      output += chunk;
106	      const match = output.match(/listening on (http:\/\/localhost:\d+)/);
107	      if (match && !settled) {
108	        settled = true;
109	        clearTimeout(timer);
110	        resolve({
111	          baseUrl: match[1].replace('localhost', '127.0.0.1'),
112	          output: () => output,
113	          stop: () =>
114	            new Promise((done) => {
115	              if (child.exitCode !== null) return done();
116	              child.once('exit', () => done());
117	              child.kill('SIGTERM');
118	              setTimeout(() => child.kill('SIGKILL'), 3000).unref();
119	            }),
120	        });
121	      }
122	    }
123	    child.stdout.on('data', onData);
124	    child.stderr.on('data', onData);
125	    child.on('error', fail);
126	    child.on('exit', (code) => fail(new Error(`Server exited early with code ${code}:\n${output}`)));
127	  });
128	}
129	
130	/** Fresh database + server in one go. `close()` stops the server and deletes the files. */
131	export async function startFreshServer(options) {
132	  const dir = createTempDir();
133	  const dbPath = path.join(dir, 'test.sqlite');
134	  const server = await startServer(dbPath, options);
135	  return {
136	    ...server,
137	    dir,
138	    dbPath,
139	    /** Row-counting connection for assertions. */
140	    openDb: () => openDatabase(dbPath),
141	    close: async () => {
142	      await server.stop();
143	      removeTempDir(dir);
144	    },
145	  };
146	}
147	
148	/**
149	 * Minimal HTTP client bound to one actor.
150	 * Responses: `{ status, headers, text, json }` (json is null for non-JSON bodies).
151	 */
152	export function clientFor(baseUrl, actorEmail) {
153	  async function request(method, urlPath, { body, headers = {}, rawBody } = {}) {
154	    const init = { method, headers: { ...headers } };
155	    if (actorEmail) init.headers['X-Actor-Email'] = actorEmail;
156	    if (rawBody !== undefined) {
157	      init.body = rawBody;
158	    } else if (body !== undefined) {
159	      init.headers['Content-Type'] = 'application/json';
160	      init.body = JSON.stringify(body);
161	    }
162	    const response = await fetch(baseUrl + urlPath, init);
163	    const text = await response.text();
164	    let json = null;
165	    if ((response.headers.get('content-type') ?? '').includes('application/json')) json = JSON.parse(text);
166	    return { status: response.status, headers: response.headers, text, json };
167	  }
168	  return {
169	    get: (urlPath, options) => request('GET', urlPath, options),
170	    post: (urlPath, body, options = {}) => request('POST', urlPath, { body, ...options }),
171	    bulkIssue: (courseId, idempotencyKey, extra = {}) =>
172	      request('POST', '/api/bulk-issues', {
173	        body: { courseId, ...extra },
174	        headers: idempotencyKey ? { 'Idempotency-Key': idempotencyKey } : {},
175	      }),
176	  };
177	}
178	
179	/** RFC 4180 parser (quoted fields, doubled quotes, embedded separators and newlines). */
180	export function parseCsv(text) {
181	  const rows = [];
182	  let row = [];
183	  let field = '';
184	  let quoted = false;
185	  for (let i = 0; i < text.length; i += 1) {
186	    const ch = text[i];
187	    if (quoted) {
188	      if (ch === '"') {
189	        if (text[i + 1] === '"') {
190	          field += '"';
191	          i += 1;
192	        } else {
193	          quoted = false;
194	        }
195	      } else {
196	        field += ch;
197	      }
198	    } else if (ch === '"') {
199	      quoted = true;
200	    } else if (ch === ',') {
201	      row.push(field);
202	      field = '';
203	    } else if (ch === '\n') {
204	      row.push(field);
205	      rows.push(row);
206	      row = [];
207	      field = '';
208	    } else if (ch !== '\r') {
209	      field += ch;
210	    }
211	  }
212	  if (field !== '' || row.length > 0) {
213	    row.push(field);
214	    rows.push(row);
215	  }
216	  return rows;
217	}
218	
219	/** Counts used by "nothing was written" assertions. */
220	export function countRows(db, tenantId) {
221	  const scope = tenantId ? ' WHERE tenant_id = @tenantId' : '';
222	  const params = tenantId ? { tenantId } : undefined;
223	  const count = (table) => db.get(`SELECT COUNT(*) AS n FROM ${table}${scope}`, params).n;
224	  return {
225	    certificates: count('certificates'),
226	    auditEvents: count('audit_events'),
227	    operations: count('bulk_issue_operations'),
228	  };
229	}
230	
231	/**
232	 * Streaming GET built on node:http so a test can stop reading mid-download.
233	 * Resolves as soon as the first body bytes arrive, with the response paused:
234	 *   { status, headers, bytesSoFar(), finished(), resume(): Promise<string> }
235	 */
236	export function openStream(baseUrl, urlPath, actorEmail) {
237	  return new Promise((resolve, reject) => {
238	    const req = http.get(baseUrl + urlPath, { headers: { 'X-Actor-Email': actorEmail } }, (res) => {
239	      const chunks = [];
240	      let bytes = 0;
241	      let ended = false;
242	      let finish;
243	      const whole = new Promise((done, failed) => {
244	        finish = done;
245	        res.on('error', failed);
246	      });
247	      res.on('end', () => {
248	        ended = true;
249	        finish(Buffer.concat(chunks).toString('utf8'));
250	      });
251	      res.on('data', (chunk) => {
252	        chunks.push(chunk);
253	        bytes += chunk.length;
254	      });
255	      res.once('data', () => {
256	        res.pause();
257	        resolve({
258	          status: res.statusCode,
259	          headers: res.headers,
260	          bytesSoFar: () => bytes,
261	          finished: () => ended,
262	          resume: () => {
263	            res.resume();
264	            return whole;
265	          },
266	          /** Simulates a client that walks away mid-download. */
267	          abort: () => {
268	            whole.catch(() => {});
269	            req.destroy();
270	          },
271	        });
272	      });
273	    });
274	    req.on('error', reject);
275	  });
276	}
277	
278	/** SQLite's NOCASE collation: ASCII letters fold, everything else compares by code point. */
279	export function nocaseCompare(a, b) {
280	  const fold = (text) => text.replace(/[A-Z]/g, (ch) => ch.toLowerCase());
281	  const x = fold(a);
282	  const y = fold(b);
283	  return x < y ? -1 : x > y ? 1 : 0;
284	}
285	
286	/** Resolves to true when `promise` has neither fulfilled nor rejected after `ms` milliseconds. */
287	export function stillPending(promise, ms) {
288	  let timer;
289	  const timeout = new Promise((resolve) => {
290	    timer = setTimeout(() => resolve(true), ms);
291	  });
292	  const settled = promise.then(
293	    () => false,
294	    () => false,
295	  );
296	  return Promise.race([settled, timeout]).finally(() => clearTimeout(timer));
297	}
298	
299	export async function timed(fn) {
300	  const started = performance.now();
301	  const value = await fn();
302	  return { value, ms: performance.now() - started };
303	}
