364	describe('A2 - while another process holds the database write lock', () => {
365	  // `locker` plays another process in the middle of a long write (the load-test generator, a
366	  // reset, ...). While it holds the lock no request can write, which makes "these two requests
367	  // overlap" a certainty instead of a matter of timing.
368	  let ctx;
369	  let second;
370	  let db;
371	  let locker;
372	  let servers;
373	  const PROMPT_MS = 1500;
374	
375	  before(async () => {
376	    ctx = await startFreshServer();
377	    second = await startServer(ctx.dbPath);
378	    db = ctx.openDb();
379	    locker = ctx.openDb();
380	    servers = [ctx.baseUrl, second.baseUrl];
381	  });
382	  after(async () => {
383	    locker.close(); // rolls back if a failed test left the lock behind
384	    db.close();
385	    await second.stop();
386	    await ctx.close();
387	  });
388	
389	  /** Runs `fn` while the write lock is held; `release()` gives it up early (with a COMMIT). */
390	  async function whileLocked(fn) {
391	    locker.exec('BEGIN IMMEDIATE');
392	    let held = true;
393	    const release = () => {
394	      if (held) locker.exec('COMMIT');
395	      held = false;
396	    };
397	    try {
398	      return await fn(release);
399	    } finally {
400	      if (held) locker.exec('ROLLBACK');
401	    }
402	  }
403	
404	  async function assertReadsAreServed(label) {
405	    for (const baseUrl of servers) {
406	      const list = await timed(() => clientFor(baseUrl, BOB).get('/api/certificates?pageSize=5'));
407	      assert.equal(list.value.status, 200);
408	      assert.ok(list.ms < PROMPT_MS, `${label}: list took ${Math.round(list.ms)} ms on ${baseUrl}`);
409	    }
410	  }
