417	      // Neither request can finish while the lock is held, so from here on both are in flight...
418	      assert.equal(await stillPending(Promise.race(requests), 400), true, 'both requests wait for the lock');
419	      // ...and neither server is frozen by its waiting request.
420	      await assertReadsAreServed('while a bulk issue waits');
