1	/**
2	 * A6 - export scalability and determinism on 100,000 East certificates.
3	 *
4	 * The dataset is produced by the real generator CLI on top of a freshly seeded database, and the
5	 * server runs as its own process, so timings reflect what a client actually experiences.
6	 */
7	import assert from 'node:assert/strict';
8	import fs from 'node:fs';
9	import path from 'node:path';
10	import { after, before, describe, it } from 'node:test';
11	
12	import { isBusyError, openDatabase } from '../src/db/sqlite.js';
13	import {
14	  ALICE,
15	  BOB,
16	  SEED,
17	  clientFor,
18	  createTempDir,
19	  nocaseCompare,
20	  openStream,
21	  parseCsv,
22	  removeTempDir,
23	  runScript,
24	  startServer,
25	  timed,
26	} from './helpers.js';
27	
28	const GENERATED = 100_000;
29	const EAST_TOTAL = SEED.east.certificateCount + GENERATED;
30	const TIME_LIMIT_MS = 60_000;
31	const plain = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
32	const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
33	
34	/** Every quick-start row, i.e. everything that is not flagged as generated. */
35	function quickStartSnapshot(db) {
36	  const rows = (sql) => db.all(sql).map((row) => ({ ...row }));
37	  const seedCourses = 'SELECT id FROM courses WHERE is_generated = 0';
38	  return {
39	    tenants: rows('SELECT id, name, code, timezone FROM tenants ORDER BY id'),
40	    admins: rows('SELECT * FROM admins ORDER BY id'),
41	    courses: rows('SELECT * FROM courses WHERE is_generated = 0 ORDER BY id'),
42	    learners: rows('SELECT * FROM learners WHERE is_generated = 0 ORDER BY id'),
43	    enrollments: rows(`SELECT * FROM enrollments WHERE course_id IN (${seedCourses}) ORDER BY id`),
44	    certificates: rows(`SELECT * FROM certificates WHERE course_id IN (${seedCourses}) ORDER BY id`),
45	    auditEvents: rows(
46	      `SELECT * FROM audit_events WHERE certificate_id IN (SELECT id FROM certificates WHERE course_id IN (${seedCourses})) ORDER BY id`,
47	    ),
48	  };
49	}
50	
51	describe('A6 - 100,000-certificate export', { timeout: 300_000 }, () => {
52	  let dir;
53	  let dbPath;
54	  let db;
55	  let server;
56	  let alice;
57	  let bob;
58	  let before100k;
59	  let generatorOutput;
60	  /** serial number -> database row, for checking order against the real sort keys. */
61	  let bySerial;
62	
