  const t = performance.now();
  http.get({ port, path, headers, agent }, (res) => { let n = 0; res.on('data', (c) => (n += c.length)); res.on('end', () => resolve({ ms: performance.now() - t, n, status: res.statusCode })); }).on('error', reject);
