     async writeTransaction(fn, { timeoutMs = LOCK_WAIT_MS, whileWaiting } = {}) {
       const deadline = monotonicNow() + timeoutMs;
       let delay = 4;
       for (;;) {
         if (this.#depth !== 0) throw new Error('writeTransaction cannot start inside another transaction');
         let busy;
         this.exec('PRAGMA busy_timeout = 0');
         try { this.exec('BEGIN IMMEDIATE'); break; }
         catch (err) { if (!isBusyError(err)) throw err; busy = err; }
         finally { this.exec(`PRAGMA busy_timeout = ${LOCK_WAIT_MS}`); }
         if (whileWaiting) { const settled = whileWaiting(); if (settled !== undefined) return settled; }
         const remaining = deadline - monotonicNow();
         if (remaining <= 0) throw busy;
         await sleep(Math.min(delay, remaining));
         delay = Math.min(delay * 2, 100);
       }
