 82	function deleteGenerated(db, tenantId) {
 83	  const params = { tenantId };
 84	  const generatedCourses = 'SELECT id FROM courses WHERE tenant_id = @tenantId AND is_generated = 1';
 85	  const generatedCertificates = `SELECT id FROM certificates WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`;
 86	  db.run(`DELETE FROM audit_events WHERE tenant_id = @tenantId AND certificate_id IN (${generatedCertificates})`, params);
 87	  const removed = db.run(`DELETE FROM certificates WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`, params).changes;
 88	  db.run(`DELETE FROM bulk_issue_operations WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`, params);
 89	  db.run(`DELETE FROM enrollments WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`, params);
 90	  db.run('DELETE FROM learners WHERE tenant_id = @tenantId AND is_generated = 1', params);
 91	  db.run('DELETE FROM courses WHERE tenant_id = @tenantId AND is_generated = 1', params);
 92	  return removed;
 93	}
