104	 * Runs in a single transaction: other connections see either none or all of the new rows.
105	 */
106	export function generateCertificates(db, { tenantName, count = 100_000, seed = 20260110 }) {
107	  if (!Number.isInteger(count) || count < 1 || count > 2_000_000) {
108	    throw new Error('count must be an integer between 1 and 2,000,000');
109	  }
110	  const { tenant, admin } = findTenant(db, tenantName);
111	  const random = createRandom(seed);
112	  const createdAt = new Date(WINDOW_START).toISOString();
113	
114	  return db.transaction(() => {
115	    const replaced = deleteGenerated(db, tenant.id);
116	
117	    // Courses and learners -----------------------------------------------------------------
118	    const courses = COURSE_TITLES.map((title) => ({
119	      title,
120	      titleKey: foldText(title),
121	      id: db.run(
122	        'INSERT INTO courses (tenant_id, title, is_generated, created_at) VALUES (@tenantId, @title, 1, @createdAt)',
123	        { tenantId: tenant.id, title, createdAt },
124	      ).lastInsertRowid,
125	    }));
126	
127	    const learnerCount = Math.ceil(count / courses.length);
128	    const learners = new Array(learnerCount);
129	    for (let i = 0; i < learnerCount; i += 1) {
130	      const name = `${FIRST_NAMES[Math.floor(random() * FIRST_NAMES.length)]} ${LAST_NAMES[Math.floor(random() * LAST_NAMES.length)]}`;
131	      learners[i] = {
132	        name,
133	        nameKey: foldText(name),
134	        id: db.run(
135	          `INSERT INTO learners (tenant_id, full_name, email, is_generated, created_at)
136	           VALUES (@tenantId, @name, @email, 1, @createdAt)`,
137	          { tenantId: tenant.id, name, email: `learner${i + 1}@loadtest.${tenant.name.toLowerCase()}.test`, createdAt },
138	        ).lastInsertRowid,
139	      };
140	    }
141	
142	    // Issue instants: sorted batch timestamps, each shared by ~25 certificates -----------------
143	    const batchCount = Math.max(1, Math.round(count / CERTIFICATES_PER_BATCH));
144	    const batchInstants = new Float64Array(batchCount);
145	    for (let b = 0; b < batchCount; b += 1) {
146	      batchInstants[b] = WINDOW_START + Math.floor((random() * (WINDOW_END - WINDOW_START)) / 1000) * 1000;
147	    }
148	    batchInstants.sort();
149	
150	    // Visit every (learner, course) pair exactly once, in a scrambled but reproducible order.
151	    let stride = 7919;
152	    while (gcd(stride, count) !== 1) stride += 2;
153	
154	    let revokedCount = 0;
155	    let previousBatch = -1;
156	    let issuedAt = '';
157	    let issuedLocalDate = '';
158	
159	    // Rows are inserted in chronological order, so ids and serial numbers follow the timeline.
160	    // (deleteGenerated above removed the previous set, so the numbering can start at 1 again.)
161	    for (let k = 0; k < count; k += 1) {
162	      const batch = Math.min(batchCount - 1, Math.floor((k * batchCount) / count));
163	      if (batch !== previousBatch) {
164	        previousBatch = batch;
165	        issuedAt = new Date(batchInstants[batch]).toISOString();
166	        issuedLocalDate = localDate(issuedAt, tenant.timezone);
167	      }
168	      const pair = (k * stride) % count;
169	      const learner = learners[Math.floor(pair / courses.length)];
170	      const course = courses[pair % courses.length];
171	      const serialNumber = formatGeneratedSerial(tenant.code, k + 1);
172	
173	      const enrollmentId = db.run(
174	        `INSERT INTO enrollments (tenant_id, course_id, learner_id, status, completed_at, created_at)
175	         VALUES (@tenantId, @courseId, @learnerId, 'completed', @completedAt, @createdAt)`,
176	        {
177	          tenantId: tenant.id,
178	          courseId: course.id,
179	          learnerId: learner.id,
180	          completedAt: new Date(batchInstants[batch] - Math.ceil(random() * 72) * HOUR).toISOString(),
181	          createdAt,
182	        },
183	      ).lastInsertRowid;
184	
185	      const revokedAt =
186	        random() < REVOKED_SHARE ? new Date(batchInstants[batch] + Math.ceil(random() * 20) * DAY).toISOString() : null;
187	      const reason = revokedAt ? 'Generated revocation (load test)' : null;
188	
189	      const certificateId = db.run(
190	        `INSERT INTO certificates (tenant_id, course_id, learner_id, enrollment_id, serial_number, learner_name, course_title,
191	                                   learner_name_key, course_title_key,
192	                                   status, issued_at, issued_local_date, issued_by_admin_id,
193	                                   revoked_at, revoked_by_admin_id, revocation_reason)
194	         VALUES (@tenantId, @courseId, @learnerId, @enrollmentId, @serialNumber, @learnerName, @courseTitle,
195	                 @learnerNameKey, @courseTitleKey,
196	                 @status, @issuedAt, @issuedLocalDate, @adminId,
197	                 @revokedAt, @revokedBy, @reason)`,
198	        {
199	          tenantId: tenant.id,
200	          courseId: course.id,
201	          learnerId: learner.id,
202	          enrollmentId,
203	          serialNumber,
204	          learnerName: learner.name,
205	          courseTitle: course.title,
206	          learnerNameKey: learner.nameKey,
207	          courseTitleKey: course.titleKey,
208	          status: revokedAt ? 'revoked' : 'active',
209	          issuedAt,
210	          issuedLocalDate,
211	          adminId: admin.id,
212	          revokedAt,
213	          revokedBy: revokedAt ? admin.id : null,
214	          reason,
215	        },
216	      ).lastInsertRowid;
217	
218	      const audit = (action, at, details) =>
219	        db.run(
220	          `INSERT INTO audit_events (tenant_id, actor_admin_id, actor_email, action, certificate_id, details, created_at)
221	           VALUES (@tenantId, @adminId, @email, @action, @certificateId, @details, @createdAt)`,
222	          {
223	            tenantId: tenant.id,
224	            adminId: admin.id,
225	            email: admin.email,
226	            action,
227	            certificateId,
228	            details: JSON.stringify(details),
229	            createdAt: at,
230	          },
231	        );
232	      audit(AUDIT_ACTIONS.ISSUED, issuedAt, {
233	        serialNumber,
234	        learnerId: learner.id,
235	        learnerName: learner.name,
236	        courseId: course.id,
237	        courseTitle: course.title,
238	        source: 'load-test-generator',
239	      });
240	      if (revokedAt) {
241	        revokedCount += 1;
242	        audit(AUDIT_ACTIONS.REVOKED, revokedAt, { serialNumber, reason, previousStatus: 'active', source: 'load-test-generator' });
243	      }
244	    }
245	
246	    return {
247	      tenant: tenant.name,
248	      generated: count,
249	      replaced,
250	      revoked: revokedCount,
251	      courses: courses.length,
252	      learners: learnerCount,
253	      distinctIssueInstants: batchCount,
254	      totalCertificatesInTenant: db.get('SELECT COUNT(*) AS n FROM certificates WHERE tenant_id = @tenantId', {
255	        tenantId: tenant.id,
256	      }).n,
257	    };
258	  });
259	}
  1	#!/usr/bin/env node
  2	/**
  3	 * Load-test data generator CLI.
  4	 *
  5	 *   npm run generate:east                     # 100,000 certificates for tenant East
  6	 *   npm run generate:east -- --count 250000   # a different volume
  7	 *   npm run generate:east -- --clear          # remove the generated rows again
  8	 *   npm run generate:east -- --db /tmp/x.sqlite   # work on another database file
  9	 *
 10	 * Safe to run while the server is up: the rows are written in one transaction and the running
 11	 * app shows them on the next request. The quick-start demo rows are never modified.
 12	 *
 13	 * Every problem ends in a short message (no stack trace) and exit code 1; nothing is written then.
 14	 */
 15	import { parseArgs } from 'node:util';
 16	
 17	import { openInitializedDatabase } from '../src/bootstrap.js';
 18	import { loadConfig, resolveUserPath } from '../src/config.js';
 19	import { clearGeneratedCertificates, generateCertificates } from '../src/db/generate.js';
 20	import { checkDatabaseSettings } from '../src/db/sqlite.js';
 21	
 22	const USAGE = 'Usage: node scripts/generate-certificates.js [--tenant East] [--count 100000] [--seed N] [--db path] [--clear]';
 23	
 24	function fail(message) {
 25	  console.error(message);
 26	  process.exit(1);
 27	}
 28	
 29	let values;
 30	try {
 31	  ({ values } = parseArgs({
 32	    options: {
 33	      tenant: { type: 'string', default: 'East' },
 34	      count: { type: 'string', default: '100000' },
 35	      seed: { type: 'string', default: '20260110' },
 36	      db: { type: 'string' },
 37	      clear: { type: 'boolean', default: false },
 38	      help: { type: 'boolean', short: 'h', default: false },
 39	    },
 40	    allowPositionals: false,
 41	  }));
 42	} catch (err) {
 43	  fail(`${err.message}\n${USAGE}`);
 44	}
 45	
 46	if (values.help) {
 47	  console.log(USAGE);
 48	  process.exit(0);
 49	}
 50	
 51	const count = Number(values.count);
 52	const seed = Number(values.seed);
 53	if (!Number.isInteger(count) || count < 1) fail(`--count must be a positive integer (got "${values.count}")`);
 54	if (!Number.isInteger(seed)) fail(`--seed must be an integer (got "${values.seed}")`);
 55	
 56	let dbPath;
 57	let db;
 58	try {
 59	  checkDatabaseSettings(); // SQLITE_DRIVER, DB_BUSY_TIMEOUT_MS
 60	  dbPath = values.db ? resolveUserPath(values.db) : loadConfig().dbPath;
 61	} catch (err) {
 62	  fail(err.message);
 63	}
 64	try {
 65	  db = openInitializedDatabase(dbPath, { log: console.log });
 66	} catch (err) {
 67	  fail(`Could not open the database at ${dbPath}: ${err.message}`);
 68	}
 69	try {
 70	  const started = performance.now();
 71	  if (values.clear) {
 72	    const result = clearGeneratedCertificates(db, { tenantName: values.tenant });
 73	    console.log(`Removed ${result.removed.toLocaleString('en-US')} generated certificates from tenant ${result.tenant}.`);
 74	  } else {
 75	    console.log(`Generating ${count.toLocaleString('en-US')} certificates for tenant ${values.tenant} in ${dbPath} ...`);
 76	    const result = generateCertificates(db, { tenantName: values.tenant, count, seed });
 77	    const seconds = ((performance.now() - started) / 1000).toFixed(1);
 78	    console.log(
 79	      `Done in ${seconds}s: ${result.generated.toLocaleString('en-US')} certificates ` +
 80	        `(${result.revoked.toLocaleString('en-US')} revoked) across ${result.courses} generated courses and ` +
 81	        `${result.learners.toLocaleString('en-US')} generated learners, ${result.distinctIssueInstants.toLocaleString('en-US')} distinct issue instants.`,
 82	    );
 83	    if (result.replaced > 0) {
 84	      console.log(`Replaced ${result.replaced.toLocaleString('en-US')} previously generated certificates.`);
 85	    }
 86	    console.log(`Tenant ${result.tenant} now has ${result.totalCertificatesInTenant.toLocaleString('en-US')} certificates in total.`);
 87	  }
 88	  // Refresh planner statistics after a large change in table sizes.
 89	  db.exec('PRAGMA optimize');
 90	} catch (err) {
 91	  console.error(`Generation failed: ${err.message}`);
 92	  process.exitCode = 1;
 93	} finally {
 94	  db.close();
 95	}
  1	#!/usr/bin/env node
  2	/**
  3	 * Database initialisation CLI.
  4	 *
  5	 *   node scripts/init-db.js           # create schema + demo data if the database is empty
  6	 *   node scripts/init-db.js --reset   # restore the pristine quick-start dataset
  7	 *
  8	 * `--reset` empties and re-seeds the tables inside one transaction; it never deletes the file of
  9	 * a usable database, so a server that has it open simply sees the fresh data afterwards. If
 10	 * another process is in the middle of a long write, the reset gives up without changing anything.
 11	 *
 12	 * Every problem ends in a short message (no stack trace) and exit code 1.
 13	 */
 14	import fs from 'node:fs';
 15	import { parseArgs } from 'node:util';
 16	
 17	import { openInitializedDatabase } from '../src/bootstrap.js';
 18	import { loadConfig, resolveUserPath } from '../src/config.js';
 19	import { SCHEMA_VERSION } from '../src/db/schema.js';
 20	import { seedDemoData } from '../src/db/seed.js';
 21	import { checkDatabaseSettings, isBusyError, openDatabase, removeDatabaseFiles } from '../src/db/sqlite.js';
 22	
 23	const USAGE = 'Usage: node scripts/init-db.js [--reset] [--db path]';
 24	
 25	function fail(message) {
 26	  console.error(message);
 27	  process.exit(1);
 28	}
 29	
 30	let values;
 31	let dbPath;
 32	try {
 33	  ({ values } = parseArgs({
 34	    options: { reset: { type: 'boolean', default: false }, db: { type: 'string' } },
 35	    allowPositionals: false,
 36	  }));
 37	} catch (err) {
 38	  fail(`${err.message}\n${USAGE}`);
 39	}
 40	try {
 41	  checkDatabaseSettings(); // SQLITE_DRIVER, DB_BUSY_TIMEOUT_MS
 42	  dbPath = values.db ? resolveUserPath(values.db) : loadConfig().dbPath;
 43	} catch (err) {
 44	  fail(err.message);
 45	}
 46	
 47	// Children before parents, so foreign keys stay satisfied at every step.
 48	const TABLES_IN_DELETE_ORDER = [
 49	  'audit_events',
 50	  'certificates',
 51	  'bulk_issue_operations',
 52	  'enrollments',
 53	  'learners',
 54	  'courses',
 55	  'admins',
 56	  'tenants',
 57	];
 58	
 59	/**
 60	 * Returns 'done', 'done-not-compacted' (data restored, but another connection kept the files from
 61	 * shrinking yet), 'empty' (nothing to reset yet) or 'incompatible' (file from another schema version).
 62	 */
 63	function resetInPlace() {
 64	  const db = openDatabase(dbPath);
 65	  try {
 66	    const { user_version: version } = db.get('PRAGMA user_version');
 67	    if (version === 0) return 'empty';
 68	    if (version !== SCHEMA_VERSION) return 'incompatible';
 69	    db.transaction(() => {
 70	      for (const table of TABLES_IN_DELETE_ORDER) db.exec(`DELETE FROM ${table}`);
 71	      seedDemoData(db);
 72	    });
 73	    try {
 74	      // Hand the space of removed load-test rows back to the file system: rebuild the file, then
 75	      // fold the write-ahead log into it (which is what actually shrinks both files on disk).
 76	      db.exec('VACUUM');
 77	      db.exec('PRAGMA busy_timeout = 1000');
 78	      // The pragma reports a checkpoint it could not finish in its "busy" column, not as an error.
 79	      const checkpoint = db.get('PRAGMA wal_checkpoint(TRUNCATE)');
 80	      return checkpoint?.busy ? 'done-not-compacted' : 'done';
 81	    } catch {
 82	      return 'done-not-compacted'; // the data is restored either way
 83	    }
 84	  } finally {
 85	    db.close();
 86	  }
 87	}
 88	
 89	if (values.reset && fs.existsSync(dbPath)) {
 90	  let outcome;
 91	  try {
 92	    outcome = resetInPlace();
 93	  } catch (err) {
 94	    // Never fall back to deleting the file here: a running server would keep writing to the
 95	    // unlinked file and everything it acknowledged afterwards would be lost.
 96	    if (isBusyError(err)) {
 97	      console.error('The database is busy (another process is writing to it). Nothing was changed; try again in a moment.');
 98	    } else {
 99	      console.error(`Reset failed, nothing was changed: ${err.message}`);
100	      console.error(`If the file is damaged, stop the server and delete ${dbPath}* to start over.`);
101	    }
102	    process.exit(1);
103	  }
104	  if (outcome === 'done' || outcome === 'done-not-compacted') {
105	    console.log(`Demo data restored in ${dbPath}`);
106	    if (outcome === 'done-not-compacted') {
107	      console.log('(A download or another connection still reads the old data; the files shrink once it has finished.)');
108	    }
109	    process.exit(0);
110	  }
111	  if (outcome === 'incompatible') {
112	    console.log('The database file was created by a different version of this app; recreating it.');
113	    console.log('(If a server is still running on it, restart that server now.)');
114	    removeDatabaseFiles(dbPath);
115	  }
116	}
117	
118	let db;
119	try {
120	  db = openInitializedDatabase(dbPath, { log: console.log });
121	} catch (err) {
122	  fail(`Could not open the database at ${dbPath}: ${err.message}`);
123	}
124	const counts = db.get(
125	  `SELECT (SELECT COUNT(*) FROM tenants) AS tenants, (SELECT COUNT(*) FROM courses) AS courses,
126	          (SELECT COUNT(*) FROM learners) AS learners, (SELECT COUNT(*) FROM certificates) AS certificates`,
127	);
128	console.log(
129	  `Database ready at ${dbPath}: ${counts.tenants} tenants, ${counts.courses} courses, ` +
130	    `${counts.learners} learners, ${counts.certificates} certificates.`,
131	);
132	db.close();
  1	/** Opens the database and makes sure it holds the schema and the quick-start demo data. */
  2	import { migrate } from './db/schema.js';
  3	import { isSeeded, seedDemoData } from './db/seed.js';
  4	import { openDatabase } from './db/sqlite.js';
  5	
  6	export function openInitializedDatabase(dbPath, { log = () => {} } = {}) {
  7	  const db = openDatabase(dbPath);
  8	  try {
  9	    migrate(db);
 10	    if (!isSeeded(db) && seedDemoData(db)) log(`Created demo data in ${dbPath}`);
 11	  } catch (err) {
 12	    db.close();
 13	    throw err;
 14	  }
 15	  return db;
 16	}

