  1	/**
  2	 * Load-test data generator: adds N certificates (100,000 by default) to one tenant.
  3	 *
  4	 * The quick-start rows are never touched. Generated certificates belong to their own generated
  5	 * courses and learners (flagged `is_generated = 1`) and are numbered in their own serial range
  6	 * (EAST-LT-0000001, ...), so the demo scenario - the "Safety 101" rosters, "Alex Lee", every seeded
  7	 * certificate, the tenant's serial counter - is exactly as before, and the next certificate issued
  8	 * through the app still gets the serial number it would have got without the load-test data.
  9	 * Running the generator again replaces the previous generated set instead of piling up on top of it.
 10	 *
 11	 * The data is deliberately full of equal sort keys, because that is what makes ordering bugs
 12	 * visible: about 2,500 distinct learner names shared by 10,000 learners, 10 course titles, and
 13	 * issue timestamps that come in batches (many certificates carry the very same instant, the way a
 14	 * real bulk issue stamps them), a few hundred per calendar day.
 15	 *
 16	 * Everything is derived from a seeded PRNG, so the same arguments always produce the same rows.
 17	 */
 18	import { foldText } from '../lib/text.js';
 19	import { localDate } from '../lib/time.js';
 20	import { AUDIT_ACTIONS } from '../services/ledger.js';
 21	
 22	const FIRST_NAMES = [
 23	  'Aaliyah', 'Aiden', 'Amelia', 'Anika', 'Arjun', 'Ava', 'Ben', 'Caleb', 'Charlotte', 'Chloe',
 24	  'Daniel', 'Elena', 'Elijah', 'Emma', 'Ethan', 'Fatima', 'Finn', 'Grace', 'Hannah', 'Harper',
 25	  'Hugo', 'Isaac', 'Isla', 'Jack', 'Jasmine', 'Kai', 'Lachlan', 'Layla', 'Leo', 'Lily',
 26	  'Lucas', 'Maya', 'Mia', 'Mohammed', 'Nina', 'Noah', 'Olivia', 'Oscar', 'Ruby', 'Ryan',
 27	  'Samir', 'Sienna', 'Sophie', 'Tane', 'Thomas', 'Violet', 'William', 'Yuki', 'Zara', 'Zoe',
 28	];
 29	
 30	const LAST_NAMES = [
 31	  'Anderson', 'Baker', 'Bennett', 'Campbell', 'Carter', 'Clarke', 'Collins', 'Cooper', 'Edwards', 'Evans',
 32	  'Fraser', 'Gray', 'Green', 'Hall', 'Harris', 'Hughes', 'Jackson', 'James', 'Kelly', 'King',
 33	  'Martin', 'Mitchell', 'Moore', 'Morgan', 'Murphy', 'Nguyen', 'Patel', 'Phillips', 'Reid', 'Roberts',
 34	  'Robinson', 'Ryan', 'Scott', 'Singh', 'Stewart', 'Taylor', 'Thompson', 'Tran', 'Turner', 'Walker',
 35	  'Wang', 'Watson', 'White', 'Williams', 'Wilson', 'Wood', 'Wright', 'Young', 'Zhang', 'Zhou',
 36	];
 37	
 38	const COURSE_TITLES = [
 39	  'Asbestos Awareness', 'Chemical Handling', 'Confined Spaces', 'Electrical Safety', 'Emergency Warden',
 40	  'Fire Extinguisher Use', 'Hazard Identification', 'Ladder Safety', 'Noise and Hearing', 'Site Induction',
 41	].map((title) => `${title} (load test)`);
 42	
 43	/** Issue instants are spread over this fixed window (kept in the past so the demo data reads naturally). */
 44	const WINDOW_START = Date.parse('2025-01-01T00:00:00.000Z');
 45	const WINDOW_END = Date.parse('2026-10-31T00:00:00.000Z');
 46	const CERTIFICATES_PER_BATCH = 25;
 47	const REVOKED_SHARE = 0.02;
 48	const HOUR = 3_600_000;
 49	const DAY = 24 * HOUR;
 50	
 51	/** Small, fast, deterministic PRNG (mulberry32). */
 52	function createRandom(seed) {
 53	  let state = seed >>> 0;
 54	  return () => {
 55	    state = (state + 0x6d2b79f5) >>> 0;
 56	    let t = state;
 57	    t = Math.imul(t ^ (t >>> 15), t | 1);
 58	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
 59	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
 60	  };
 61	}
 62	
 63	const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
 64	
 65	/** Serial numbers of generated certificates: a range of their own, restarted with every run. */
 66	export function formatGeneratedSerial(tenantCode, sequence) {
 67	  return `${tenantCode}-LT-${String(sequence).padStart(7, '0')}`;
 68	}
 69	
 70	function findTenant(db, tenantName) {
 71	  const tenant = db.get('SELECT id, name, code, timezone FROM tenants WHERE name = @name COLLATE NOCASE', {
 72	    name: tenantName,
 73	  });
 74	  if (!tenant) throw new Error(`Unknown tenant "${tenantName}"`);
 75	  const admin = db.get('SELECT id, email FROM admins WHERE tenant_id = @tenantId ORDER BY id LIMIT 1', {
 76	    tenantId: tenant.id,
 77	  });
 78	  if (!admin) throw new Error(`Tenant "${tenant.name}" has no admin to attribute the certificates to`);
 79	  return { tenant, admin };
 80	}
 81	
 82	function deleteGenerated(db, tenantId) {
 83	  const params = { tenantId };
 84	  const generatedCourses = 'SELECT id FROM courses WHERE tenant_id = @tenantId AND is_generated = 1';
 85	  const generatedCertificates = `SELECT id FROM certificates WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`;
 86	  db.run(`DELETE FROM audit_events WHERE tenant_id = @tenantId AND certificate_id IN (${generatedCertificates})`, params);
 87	  const removed = db.run(`DELETE FROM certificates WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`, params).changes;
 88	  db.run(`DELETE FROM bulk_issue_operations WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`, params);
 89	  db.run(`DELETE FROM enrollments WHERE tenant_id = @tenantId AND course_id IN (${generatedCourses})`, params);
 90	  db.run('DELETE FROM learners WHERE tenant_id = @tenantId AND is_generated = 1', params);
 91	  db.run('DELETE FROM courses WHERE tenant_id = @tenantId AND is_generated = 1', params);
 92	  return removed;
 93	}
 94	
 95	/** Removes every generated row of the tenant; the quick-start dataset is left exactly as it was. */
 96	export function clearGeneratedCertificates(db, { tenantName }) {
 97	  const { tenant } = findTenant(db, tenantName);
 98	  const removed = db.transaction(() => deleteGenerated(db, tenant.id));
 99	  return { tenant: tenant.name, removed };
100	}
101	
102	/**
103	 * Generates `count` certificates for the tenant, replacing any previously generated set.
104	 * Runs in a single transaction: other connections see either none or all of the new rows.
105	 */
106	export function generateCertificates(db, { tenantName, count = 100_000, seed = 20260110 }) {
107	  if (!Number.isInteger(count) || count < 1 || count > 2_000_000) {
108	    throw new Error('count must be an integer between 1 and 2,000,000');
109	  }
110	  const { tenant, admin } = findTenant(db, tenantName);
111	  const random = createRandom(seed);
112	  const createdAt = new Date(WINDOW_START).toISOString();
113	
114	  return db.transaction(() => {
115	    const replaced = deleteGenerated(db, tenant.id);
116	
117	    // Courses and learners -----------------------------------------------------------------
118	    const courses = COURSE_TITLES.map((title) => ({
119	      title,
120	      titleKey: foldText(title),
121	      id: db.run(
122	        'INSERT INTO courses (tenant_id, title, is_generated, created_at) VALUES (@tenantId, @title, 1, @createdAt)',
123	        { tenantId: tenant.id, title, createdAt },
124	      ).lastInsertRowid,
125	    }));
126	
127	    const learnerCount = Math.ceil(count / courses.length);
128	    const learners = new Array(learnerCount);
129	    for (let i = 0; i < learnerCount; i += 1) {
130	      const name = `${FIRST_NAMES[Math.floor(random() * FIRST_NAMES.length)]} ${LAST_NAMES[Math.floor(random() * LAST_NAMES.length)]}`;
131	      learners[i] = {
132	        name,
133	        nameKey: foldText(name),
134	        id: db.run(
135	          `INSERT INTO learners (tenant_id, full_name, email, is_generated, created_at)
136	           VALUES (@tenantId, @name, @email, 1, @createdAt)`,
137	          { tenantId: tenant.id, name, email: `learner${i + 1}@loadtest.${tenant.name.toLowerCase()}.test`, createdAt },
138	        ).lastInsertRowid,
139	      };
140	    }
141	
142	    // Issue instants: sorted batch timestamps, each shared by ~25 certificates -----------------
143	    const batchCount = Math.max(1, Math.round(count / CERTIFICATES_PER_BATCH));
144	    const batchInstants = new Float64Array(batchCount);
145	    for (let b = 0; b < batchCount; b += 1) {
146	      batchInstants[b] = WINDOW_START + Math.floor((random() * (WINDOW_END - WINDOW_START)) / 1000) * 1000;
147	    }
148	    batchInstants.sort();
149	
150	    // Visit every (learner, course) pair exactly once, in a scrambled but reproducible order.
151	    let stride = 7919;
152	    while (gcd(stride, count) !== 1) stride += 2;
153	
154	    let revokedCount = 0;
155	    let previousBatch = -1;
156	    let issuedAt = '';
157	    let issuedLocalDate = '';
158	
159	    // Rows are inserted in chronological order, so ids and serial numbers follow the timeline.
160	    // (deleteGenerated above removed the previous set, so the numbering can start at 1 again.)
