  2	/**
  3	 * Database initialisation CLI.
  4	 *
  5	 *   node scripts/init-db.js           # create schema + demo data if the database is empty
  6	 *   node scripts/init-db.js --reset   # restore the pristine quick-start dataset
  7	 *
  8	 * `--reset` empties and re-seeds the tables inside one transaction; it never deletes the file of
  9	 * a usable database, so a server that has it open simply sees the fresh data afterwards. If
 10	 * another process is in the middle of a long write, the reset gives up without changing anything.
 11	 *
 12	 * Every problem ends in a short message (no stack trace) and exit code 1.
 13	 */
 14	import fs from 'node:fs';
 15	import { parseArgs } from 'node:util';
 16	
 17	import { openInitializedDatabase } from '../src/bootstrap.js';
 18	import { loadConfig, resolveUserPath } from '../src/config.js';
 19	import { SCHEMA_VERSION } from '../src/db/schema.js';
 20	import { seedDemoData } from '../src/db/seed.js';
 21	import { checkDatabaseSettings, isBusyError, openDatabase, removeDatabaseFiles } from '../src/db/sqlite.js';
 22	
 23	const USAGE = 'Usage: node scripts/init-db.js [--reset] [--db path]';
 24	
 25	function fail(message) {
 26	  console.error(message);
 27	  process.exit(1);
 28	}
 29	
 30	let values;
 31	let dbPath;
 32	try {
 33	  ({ values } = parseArgs({
 34	    options: { reset: { type: 'boolean', default: false }, db: { type: 'string' } },
 35	    allowPositionals: false,
 36	  }));
 37	} catch (err) {
 38	  fail(`${err.message}\n${USAGE}`);
 39	}
 40	try {
 41	  checkDatabaseSettings(); // SQLITE_DRIVER, DB_BUSY_TIMEOUT_MS
 42	  dbPath = values.db ? resolveUserPath(values.db) : loadConfig().dbPath;
 43	} catch (err) {
 44	  fail(err.message);
 45	}
 46	
 47	// Children before parents, so foreign keys stay satisfied at every step.
 48	const TABLES_IN_DELETE_ORDER = [
 49	  'audit_events',
 50	  'certificates',
 51	  'bulk_issue_operations',
 52	  'enrollments',
 53	  'learners',
 54	  'courses',
 55	  'admins',
 56	  'tenants',
 57	];
 58	
 59	/**
 60	 * Returns 'done', 'done-not-compacted' (data restored, but another connection kept the files from
 61	 * shrinking yet), 'empty' (nothing to reset yet) or 'incompatible' (file from another schema version).
 62	 */
 63	function resetInPlace() {
 64	  const db = openDatabase(dbPath);
 65	  try {
 66	    const { user_version: version } = db.get('PRAGMA user_version');
 67	    if (version === 0) return 'empty';
 68	    if (version !== SCHEMA_VERSION) return 'incompatible';
 69	    db.transaction(() => {
 70	      for (const table of TABLES_IN_DELETE_ORDER) db.exec(`DELETE FROM ${table}`);
 71	      seedDemoData(db);
 72	    });
 73	    try {
 74	      // Hand the space of removed load-test rows back to the file system: rebuild the file, then
 75	      // fold the write-ahead log into it (which is what actually shrinks both files on disk).
 76	      db.exec('VACUUM');
 77	      db.exec('PRAGMA busy_timeout = 1000');
 78	      // The pragma reports a checkpoint it could not finish in its "busy" column, not as an error.
 79	      const checkpoint = db.get('PRAGMA wal_checkpoint(TRUNCATE)');
 80	      return checkpoint?.busy ? 'done-not-compacted' : 'done';
 81	    } catch {
 82	      return 'done-not-compacted'; // the data is restored either way
 83	    }
 84	  } finally {
 85	    db.close();
 86	  }
 87	}
 88	
 89	if (values.reset && fs.existsSync(dbPath)) {
 90	  let outcome;
 91	  try {
 92	    outcome = resetInPlace();
 93	  } catch (err) {
 94	    // Never fall back to deleting the file here: a running server would keep writing to the
 95	    // unlinked file and everything it acknowledged afterwards would be lost.
 96	    if (isBusyError(err)) {
 97	      console.error('The database is busy (another process is writing to it). Nothing was changed; try again in a moment.');
 98	    } else {
 99	      console.error(`Reset failed, nothing was changed: ${err.message}`);
100	      console.error(`If the file is damaged, stop the server and delete ${dbPath}* to start over.`);
101	    }
102	    process.exit(1);
103	  }
104	  if (outcome === 'done' || outcome === 'done-not-compacted') {
105	    console.log(`Demo data restored in ${dbPath}`);
106	    if (outcome === 'done-not-compacted') {
107	      console.log('(A download or another connection still reads the old data; the files shrink once it has finished.)');
108	    }
109	    process.exit(0);
110	  }
111	  if (outcome === 'incompatible') {
112	    console.log('The database file was created by a different version of this app; recreating it.');
113	    console.log('(If a server is still running on it, restart that server now.)');
114	    removeDatabaseFiles(dbPath);
115	  }
116	}
117	
118	let db;
119	try {
120	  db = openInitializedDatabase(dbPath, { log: console.log });
121	} catch (err) {
122	  fail(`Could not open the database at ${dbPath}: ${err.message}`);
123	}
124	const counts = db.get(
125	  `SELECT (SELECT COUNT(*) FROM tenants) AS tenants, (SELECT COUNT(*) FROM courses) AS courses,
126	          (SELECT COUNT(*) FROM learners) AS learners, (SELECT COUNT(*) FROM certificates) AS certificates`,
127	);
128	console.log(
129	  `Database ready at ${dbPath}: ${counts.tenants} tenants, ${counts.courses} courses, ` +
130	    `${counts.learners} learners, ${counts.certificates} certificates.`,
131	);
132	db.close();
