  2	import { migrate } from './db/schema.js';
  3	import { isSeeded, seedDemoData } from './db/seed.js';
  4	import { openDatabase } from './db/sqlite.js';
  5	
  6	export function openInitializedDatabase(dbPath, { log = () => {} } = {}) {
  7	  const db = openDatabase(dbPath);
  8	  try {
  9	    migrate(db);
 10	    if (!isSeeded(db) && seedDemoData(db)) log(`Created demo data in ${dbPath}`);
 11	  } catch (err) {
 12	    db.close();
 13	    throw err;
 14	  }
 15	  return db;
 16	}

