    // Runs on completion, on error, and when the export is abandoned mid-download.
    try {
      rows?.return?.();
    } catch {
      // statement already finished
    }
    try {
      reader.exec('ROLLBACK');
    } catch {
      // no transaction left to close
    }
  }
