python3 - <<'EOF'
import pathlib
p = pathlib.Path('test/helpers.js')
s = p.read_text()

old = "import http from 'node:http';\nimport os from 'node:os';\n"
new = "import http from 'node:http';\nimport net from 'node:net';\nimport os from 'node:os';\n"
assert old in s; s = s.replace(old, new)

old = '''/**
 * What search and sort are expected to make of a name: case and accents do not count. Written
'''
new = '''/** Splits what a server sent on one connection into its HTTP responses; an incomplete last one is left out. */
function parseResponses(buffer) {
  const responses = [];
  let offset = 0;
  for (;;) {
    const headEnd = buffer.indexOf('\\r\\n\\r\\n', offset);
    if (headEnd < 0) return responses;
    const [statusLine, ...headerLines] = buffer.toString('latin1', offset, headEnd).split('\\r\\n');
    const headers = Object.fromEntries(
      headerLines.map((line) => [line.slice(0, line.indexOf(':')).toLowerCase(), line.slice(line.indexOf(':') + 1).trim()]),
    );
    let position = headEnd + 4;
    const parts = [];
    if (/chunked/i.test(headers['transfer-encoding'] ?? '')) {
      for (;;) {
        const lineEnd = buffer.indexOf('\\r\\n', position);
        if (lineEnd < 0) return responses;
        const size = Number.parseInt(buffer.toString('latin1', position, lineEnd), 16);
        const dataEnd = lineEnd + 2 + size;
        if (dataEnd + 2 > buffer.length) return responses;
        parts.push(buffer.subarray(lineEnd + 2, dataEnd));
        position = dataEnd + 2;
        if (size === 0) break;
      }
    } else {
      const length = Number(headers['content-length'] ?? 0);
      if (position + length > buffer.length) return responses;
      parts.push(buffer.subarray(position, position + length));
      position += length;
    }
    responses.push({ status: Number(statusLine.split(' ')[1]), headers, body: Buffer.concat(parts).toString('utf8') });
    offset = position;
  }
}

/**
 * Sends several GET requests on one connection without waiting for the answers (HTTP pipelining),
 * which neither fetch nor node:http ever does. Resolves once the requests are on their way; until
 * `responses()` is called the client reads nothing at all.
 *   { responses(count): Promise<[{ status, headers, body }]>, close() }
 */
export function sendPipelined(baseUrl, urlPaths, actorEmail) {
  const { hostname, port } = new URL(baseUrl);
  return new Promise((resolve, reject) => {
    const socket = net.connect(Number(port), hostname);
    socket.pause();
    socket.once('error', reject);
    socket.once('connect', () => {
      socket.on('error', () => {}); // a server that drops the connection is something tests assert on, not a crash
      const requests = urlPaths.map((urlPath) => `GET ${urlPath} HTTP/1.1\\r\\nHost: ${hostname}\\r\\nX-Actor-Email: ${actorEmail}\\r\\n\\r\\n`);
      socket.write(requests.join(''), () =>
        resolve({
          /** Reads until `count` complete responses have arrived. */
          responses: (count, { timeoutMs = 10_000 } = {}) =>
            new Promise((done, failed) => {
              let received = Buffer.alloc(0);
              const giveUp = (why) =>
                failed(new Error(`${why}: ${parseResponses(received).length} of ${count} pipelined responses arrived`));
              const timer = setTimeout(() => giveUp(`no more data after ${timeoutMs} ms`), timeoutMs);
              socket.on('data', (chunk) => {
                received = Buffer.concat([received, chunk]);
                const parsed = parseResponses(received);
                if (parsed.length < count) return;
                clearTimeout(timer);
                done(parsed);
              });
              socket.once('close', () => {
                clearTimeout(timer);
                giveUp('the connection was closed');
              });
              socket.resume();
            }),
          /** The client walks away, whatever is still outstanding. */
          close: () => socket.destroy(),
        }),
      );
    });
  });
}

/**
 * What search and sort are expected to make of a name: case and accents do not count. Written
'''
assert old in s; s = s.replace(old, new)
p.write_text(s)

p = pathlib.Path('test/acceptance.test.js')
s = p.read_text()

old = "  runServerToExit,\n  startFreshServer,\n"
new = "  runServerToExit,\n  sendPipelined,\n  startFreshServer,\n"
assert old in s; s = s.replace(old, new)

old = '''  /** Stands in for a reader connection on a table that never ends, so that a download can be made to stall. */
  function endlessReader() {
    const row = { learner_name: 'x'.repeat(200), course_title: 'Endless', serial_number: 'E-1', issued_at: '2026-01-10T13:30:00.000Z' };
'''
new = '''  /**
   * Stands in for a reader connection on a table that never ends, so that a download can be made
   * to stall. With `matching` false no row passes the request's filter: the export reads on and on
   * without ever having anything to send.
   */
  function endlessReader({ matching = true } = {}) {
    const row = {
      learner_name: 'x'.repeat(200),
      course_title: 'Endless',
      serial_number: 'E-1',
      issued_at: '2026-01-10T13:30:00.000Z',
      matches: matching ? 1 : 0,
    };
'''
assert old in s; s = s.replace(old, new)

old = "        const reader = state.endless ? endlessReader() : openDatabase(dbPath, { queryOnly: true });\n"
new = "        const reader = state.endless ? endlessReader({ matching: state.endless !== 'without matches' }) : openDatabase(dbPath, { queryOnly: true });\n"
assert old in s; s = s.replace(old, new)

old = "    assert.ok(app.logged.some((line) => /\\[export\\] download dropped: the client accepted no data for 250 ms/.test(line)), app.logged.join('\\n'));\n"
new = "    assert.ok(app.logged.some((line) => /\\[export\\] download dropped: the client took no more data for 250 ms/.test(line)), app.logged.join('\\n'));\n"
assert old in s, 'log regex'; s = s.replace(old, new)

old = '''  it('an export that cannot even start gives its slot back and answers with a proper error', async () => {'''
new = '''  it('requests sent ahead on one connection (pipelining) hold no slot until they can be answered, and nothing once the connection is gone', async () => {
    const app = await startApp({ exportIdleTimeoutMs: 0 });
    assert.equal(app.slots.active, 0);

    // Five exports in one go; the client reads nothing, so the first answer stays in flight.
    app.endless = true;
