      for (const jumpMs of [3_600_000, -3_600_000]) {
        const started = performance.now();
        const attempt = db.writeTransaction(() => 'ran', { timeoutMs: 300 });
        attempt.catch(() => {}); // asserted on below
        setTimeout(() => {
