          if (closeSendingSide) socket.end(); // "I have nothing more to say" - but it keeps reading
          if (pauseMs) {
            socket.pause();
            setTimeout(() => socket.resume(), pauseMs);
          }
        }
        bytes += chunk.length;
      });
      socket.on('end', () => finish('ended'));
