  1	import { useEffect, useRef, useState } from 'react';
  2	
  3	import { navigate, useDebouncedValue, useQuery } from '../hooks.js';
  4	import CertificateDetail from './CertificateDetail.jsx';
  5	import { EmptyState, ErrorState, Pagination, Spinner, StatusBadge } from './ui.jsx';
  6	
  7	const COLUMNS = [
  8	  { field: 'serial', label: 'Serial number', defaultOrder: 'asc' },
  9	  { field: 'learner', label: 'Learner', defaultOrder: 'asc' },
 10	  { field: 'course', label: 'Course', defaultOrder: 'asc' },
 11	  { field: 'issued', label: 'Issued', defaultOrder: 'desc' },
 12	  { field: 'status', label: 'Status', defaultOrder: 'asc' },
 13	];
 14	
 15	const SORT_OPTIONS = [
 16	  { value: 'issued:desc', label: 'Issue date – newest first' },
 17	  { value: 'issued:asc', label: 'Issue date – oldest first' },
 18	  { value: 'learner:asc', label: 'Learner – A to Z' },
 19	  { value: 'learner:desc', label: 'Learner – Z to A' },
 20	  { value: 'course:asc', label: 'Course – A to Z' },
 21	  { value: 'course:desc', label: 'Course – Z to A' },
 22	  { value: 'serial:asc', label: 'Serial number – ascending' },
 23	  { value: 'serial:desc', label: 'Serial number – descending' },
 24	  { value: 'status:asc', label: 'Status – active first' },
 25	  { value: 'status:desc', label: 'Status – revoked first' },
 26	];
 27	
 28	const PAGE_SIZES = [10, 25, 50, 100];
 29	
 30	/**
 31	 * The search text as it is sent to the server. Pasted text easily carries tabs or line breaks
 32	 * (two spreadsheet cells, a line of an e-mail) and the server rejects control characters with a
 33	 * 400, so every run of them - together with the spaces around it - becomes a single space.
 34	 */
 35	function toSearchQuery(text) {
 36	  return text.replace(/ *[\u0000-\u001f\u007f][\u0000-\u001f\u007f ]*/g, ' ').trim();
 37	}
 38	
 39	function formatBytes(bytes) {
 40	  if (bytes < 1024) return `${bytes} B`;
 41	  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
 42	  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
 43	}
 44	
 45	export default function CertificatesPage({ api, actor, selectedCertificateId }) {
 46	  const [searchText, setSearchText] = useState('');
 47	  const [search, setSearch] = useDebouncedValue(toSearchQuery(searchText), 300);
 48	  const [status, setStatus] = useState('all');
 49	  const [sort, setSort] = useState({ field: 'issued', order: 'desc' });
 50	  const [pageSize, setPageSize] = useState(25);
 51	
 52	  // The page number belongs to one particular search/sort. Whenever those change, the list starts
 53	  // over at page 1 in the same render - no extra request for a page of the previous result set.
 54	  const filterKey = JSON.stringify([search, status, sort.field, sort.order, pageSize]);
 55	  const [pageState, setPageState] = useState({ key: filterKey, page: 1 });
 56	  const page = pageState.key === filterKey ? pageState.page : 1;
 57	  const setPage = (next) => setPageState({ key: filterKey, page: next });
 58	
 59	  const filters = { q: search, status, sort: sort.field, order: sort.order };
 60	  const list = useQuery((signal) => api.listCertificates({ ...filters, page, pageSize }, signal), [api, filterKey, page]);
 61	  const { data } = list;
 62	
 63	  // If rows disappeared underneath us (the last page no longer exists), step back to the last page.
 64	  useEffect(() => {
 65	    if (list.status === 'success' && data.items.length === 0 && data.total > 0 && page > data.totalPages) {
 66	      setPageState({ key: filterKey, page: data.totalPages });
 67	    }
 68	  }, [list.status, data, page, filterKey]);
 69	
 70	  const [exportState, setExportState] = useState({ status: 'idle' });
 71	  // The export belongs to this page. When the page goes away - another tab, another actor - a
 72	  // download still in flight is cancelled; otherwise the file would be saved later with nothing on
 73	  // screen to explain it, possibly a file of tenant A while the console is acting as tenant B.
 74	  const exportAbort = useRef(null);
 75	  useEffect(() => () => exportAbort.current?.abort(), []);
 76	
 77	  async function handleExport() {
 78	    if (exportState.status === 'running') return; // one export at a time per window
 79	    const q = toSearchQuery(searchText);
 80	    setSearch(q); // apply pending keystrokes now, so the table and the file show the same rows
 81	    setExportState({ status: 'running' });
 82	    const controller = new AbortController();
 83	    exportAbort.current = controller;
 84	    try {
 85	      const result = await api.exportCsv({ q, status, sort: sort.field, order: sort.order }, controller.signal);
 86	      setExportState({ status: 'done', ...result });
 87	    } catch (error) {
 88	      if (controller.signal.aborted) return; // the page is gone: nothing to report, nobody to tell
 89	      setExportState({ status: 'error', error });
 90	    }
 91	  }
 92	
 93	  function sortBy(column) {
 94	    setSort((current) =>
 95	      current.field === column.field
 96	        ? { field: column.field, order: current.order === 'asc' ? 'desc' : 'asc' }
 97	        : { field: column.field, order: column.defaultOrder },
 98	    );
 99	  }
100	
101	  function clearFilters() {
102	    setSearchText('');
103	    setSearch('');
104	    setStatus('all');
105	  }
106	
107	  const hasFilters = search !== '' || status !== 'all';
108	  const isFirstLoad = list.status === 'loading' && !data;
109	  const isRefreshing = list.status === 'loading' && Boolean(data);
110	
111	  return (
112	    <>
113	      <section className="panel" aria-labelledby="certificates-heading">
114	        <div className="panel-header">
115	          <div>
116	            <h1 id="certificates-heading">Certificates</h1>
117	            <p className="muted">
118	              Tenant <strong>{actor.tenant.name}</strong> · issue dates are shown in {actor.tenant.timezone} local time
119	            </p>
120	          </div>
121	          <div className="panel-actions">
122	            <button
123	              type="button"
124	              className="btn"
125	              onClick={handleExport}
126	              disabled={exportState.status === 'running'}
127	              data-testid="export-button"
128	            >
129	              {exportState.status === 'running' ? <Spinner label="Exporting…" /> : 'Export CSV'}
130	            </button>

