:root {
  --bg: #f4f6fa;
  --surface: #ffffff;
  --border: #dde2ea;
  --border-strong: #c4ccd8;
  --text: #1c2430;
  --muted: #5d6878;
  --primary: #1f4fd8;
  --primary-dark: #173fb0;
  --danger: #c2281d;
  --danger-dark: #9c1f16;
  --success-bg: #e6f5ec;
  --success-text: #17663a;
  --warn-bg: #fdf3d8;
  --warn-text: #7a5600;
  --error-bg: #fdecea;
  --error-text: #9c1f16;
  --info-bg: #eaf0fe;
  --info-text: #1d3f9e;
  --radius: 8px;
  --shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 1px 3px rgba(16, 24, 40, 0.08);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 15px;
  line-height: 1.45;
  color: var(--text);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
}

h1,
h2,
h3 {
  margin: 0;
  line-height: 1.25;
}

h1 {
  font-size: 1.35rem;
}

h2 {
  font-size: 1.1rem;
}

h3 {
  font-size: 0.95rem;
  margin: 1.5rem 0 0.5rem;
}

p {
  margin: 0.25rem 0 0;
}

a {
  color: var(--primary);
}

.muted {
  color: var(--muted);
}

.small {
  font-size: 0.85rem;
}

.mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.92em;
}

.nowrap {
  white-space: nowrap;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Layout ------------------------------------------------------------------------------------ */

.app {
  min-height: 100vh;
}

.boot {
  max-width: 560px;
  margin: 20vh auto 0;
  padding: 0 1rem;
  text-align: center;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
  padding: 0.6rem 1.5rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 5;
}

.topbar-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 650;
}

.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  border-radius: 6px;
  background: var(--primary);
  color: #fff;
  font-size: 0.95rem;
}

.tabs {
  display: flex;
  gap: 0.25rem;
  flex: 1;
}

.tab {
  padding: 0.45rem 0.85rem;
  border-radius: 6px;
  color: var(--muted);
  text-decoration: none;
  font-weight: 550;
}

.tab:hover {
  background: var(--bg);
  color: var(--text);
}

.tab-active,
.tab-active:hover {
  background: var(--info-bg);
