/** Starts a backend (API + built UI) on `port` with a database of its own. */
async function startBackend(port, dbName, { env = {}, fresh = true, copyFrom = null } = {}) {
  const dbPath = path.join(FB, 'db', `${dbName}.sqlite`);
  if (fresh) for (const suffix of ['', '-wal', '-shm']) fs.rmSync(dbPath + suffix, { force: true });
  if (copyFrom) fs.copyFileSync(copyFrom, dbPath);
  const logPath = path.join(FB, 'logs', `backend-${port}-${dbName}.log`);
  const out = fs.openSync(logPath, 'w');
  const child = spawn(process.execPath, ['backend/src/server.js'], {
    cwd: APP,
    env: { ...process.env, PORT: String(port), HOST: '127.0.0.1', DB_PATH: dbPath, ...env },
    stdio: ['ignore', out, out],
  });
  started.push({ kind: 'backend', pid: child.pid, port, child });
  fs.appendFileSync(path.join(FB, 'run', 'PIDS-scripts.txt'), `${child.pid} backend port ${port} db ${dbName} (script ${path.basename(process.argv[1])})\n`);
  await waitForHttp(`http://127.0.0.1:${port}/api/health`);
  return {
    port,
    pid: child.pid,
    url: `http://127.0.0.1:${port}`,
    dbPath,
    logPath,
    log: () => fs.readFileSync(logPath, 'utf8'),
    reset() {
      const res = spawnSync(process.execPath, ['backend/scripts/init-db.js', '--reset', '--db', dbPath], { cwd: APP, encoding: 'utf8' });
      if (res.status !== 0) throw new Error(`db reset failed: ${res.stdout}${res.stderr}`);
    },
    async stop() {
      child.kill('SIGTERM');
      await new Promise((resolve) => (child.exitCode !== null ? resolve() : child.once('exit', resolve)));
    },
  };
}

/** Resets a database file in place with the project's own command (works while a server has it open). */
function resetDb(dbPath) {
  const res = spawnSync(process.execPath, ['backend/scripts/init-db.js', '--reset', '--db', dbPath], { cwd: APP, encoding: 'utf8' });
  if (res.status !== 0) throw new Error(`db reset failed: ${res.stdout}${res.stderr}`);
  return res.stdout;
}

/** Independent look into a database file through python3's sqlite3 (read only). */
function sql(dbPath, query, params = []) {
  const script = `
import sqlite3, json, sys
con = sqlite3.connect('file:' + sys.argv[1] + '?mode=ro', uri=True, timeout=15)
cur = con.execute(sys.argv[2], json.loads(sys.argv[3]))
print(json.dumps([list(r) for r in cur.fetchall()]))
`;
  const res = spawnSync('python3', ['-c', script, dbPath, query, JSON.stringify(params)], { encoding: 'utf8' });
  if (res.status !== 0) throw new Error(res.stderr);
  return JSON.parse(res.stdout);
}

/** Holds SQLite's write lock on `dbPath` from python3 (BEGIN IMMEDIATE) until release() or `maxSeconds`. */
async function holdWriteLock(dbPath, maxSeconds = 60) {
  const script = `
import sqlite3, sys, time
con = sqlite3.connect(sys.argv[1], timeout=20, isolation_level=None)
con.execute('BEGIN IMMEDIATE')
print('locked', flush=True)
deadline = time.time() + float(sys.argv[2])
import select
while time.time() < deadline:
    r, _, _ = select.select([sys.stdin], [], [], 0.1)
    if r:
        break
con.execute('ROLLBACK')
print('released', flush=True)
`;
  const child = spawn('python3', ['-c', script, dbPath, String(maxSeconds)], { stdio: ['pipe', 'pipe', 'inherit'] });
  started.push({ kind: 'lock', pid: child.pid, child });
  let buffer = '';
  await new Promise((resolve, reject) => {
    child.stdout.on('data', (chunk) => {
      buffer += chunk.toString();
      if (buffer.includes('locked')) resolve();
    });
    child.once('exit', () => reject(new Error('lock holder exited early')));
  });
  return {
    pid: child.pid,
    async release() {
      if (child.exitCode !== null) return;
      child.stdin.write('x\n');
      await new Promise((resolve) => child.once('exit', resolve));
    },
  };
}

