    'assignment': re.compile(r'(?i)\b([A-Z0-9_]*(?:TOKEN|SECRET|PASSWORD|PASSWD|API_?KEY|CREDENTIAL|SESSION_KEY|AUTH)[A-Z0-9_]*)\s*[=:]\s*["\']?([^\s"\'\\,;]{8,})'),
}

