def export_text_file(source, target, rules, compress=False, per_line_json=True):
    """Copy a JSON Lines (or JSON, or text) file with the rules for assignment entries applied."""
    opener = (lambda p: gzip.open(p, 'wt', encoding='utf-8', compresslevel=9)) if compress else (lambda p: open(p, 'w', encoding='utf-8'))
