    """An entry of the unrelated request: keep its skeleton, withhold what it says."""
    out = {}
    for key, value in entry.items():
        if key in STRUCTURAL_KEYS or value is None or isinstance(value, (bool, int, float)):
            out[key] = value
        elif key == 'message' and isinstance(value, dict):
            message = {}
            for mkey, mvalue in value.items():
                if mkey in MESSAGE_KEYS:
                    message[mkey] = mvalue
