  viteBin = path.join(path.dirname(require.resolve('vite/package.json')), 'bin', 'vite.js');
} catch {
  console.error('The dependencies are not installed yet. Run "npm start" once (or "npm install"), then "npm run dev" again.');
  process.exit(1);
