#!/usr/bin/env python3
"""Final checks on a staged ai/ directory. Prints counts and places only, never the matched text.

usage: final_checks.py <stage>/ai [--details]
"""
import collections, glob, gzip, json, os, re, sys

X = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, X)
import export_sessions as ex

stage = os.path.abspath(sys.argv[1])
details = '--details' in sys.argv
config = json.load(open(os.path.join(X, 'private-config.json'), encoding='utf-8'))
main_name = config['session_id'] + '.jsonl'
verbatim_lines = {i + 1 for i in config.get('verbatim_entries', [])}


def read(path):
    if path.endswith('.gz'):
        with gzip.open(path, 'rt', encoding='utf-8') as handle:
            return handle.read()
    with open(path, encoding='utf-8', errors='replace') as handle:
        return handle.read()


files = sorted(p for p in glob.glob(os.path.join(stage, '**', '*'), recursive=True) if os.path.isfile(p))
texts = {os.path.relpath(p, stage): read(p) for p in files}
problems = 0


def report(title, hits, allowed=''):
    """hits: Counter of place -> n"""
    global problems
    total = sum(hits.values())
    print(f'{"ok  " if not total else "LOOK"} {title}: {total}{" (" + allowed + ")" if allowed else ""}')
    if total:
        problems += 1
        for place, n in hits.most_common(12 if not details else 200):
            print(f'       {n:5d}  {place}')


# 1. the configured private terms
keyword = re.compile(config['private_keywords'], re.I)
tokens = [re.compile(rx, re.I) for rx, _ in config.get('private_tokens', [])]
literals = [re.compile(re.escape(text), re.I) for text in config.get('literals', {})]
families = '|'.join(config['model_families'])
model = re.compile(r'claude-(?:\d+-)*(?:' + families + r')|\b(?:' + families + r')\b', re.I)

kw_hits, token_hits, literal_hits, model_hits = (collections.Counter() for _ in range(4))
for rel, text in texts.items():
    is_main = rel.endswith(main_name)
    for number, line in enumerate(text.split('\n'), 1):
        place = f'{rel}:{number}' if is_main else rel
        if keyword.search(line) and not (is_main and number in verbatim_lines):
            kw_hits[place] += len(keyword.findall(line))
        for rx in tokens:
            n = len(rx.findall(line))
            if n and not (is_main and number in verbatim_lines):
                token_hits[place] += n
        for rx in literals:
            n = len(rx.findall(line))
            if n:
                literal_hits[place] += n
        n = len(model.findall(line))
        if n:
            model_hits[place] += n
# the reading copy repeats the candidate's request as typed
readable_ok = collections.Counter({k: v for k, v in kw_hits.items() if 'readable/' in k})
for k in readable_ok:
    del kw_hits[k]
report('private keywords outside the request as typed', kw_hits)
print(f'       (in the reading copy, where the request as typed is repeated: {sum(readable_ok.values())} in {len(readable_ok)} file(s))')
report('names (token rules) outside the request as typed', token_hits)
report('candidate e-mail address or account identifiers', literal_hits)
report('model names', model_hits)

# 2. e-mail addresses that remain
[REDACTED: text shown while this export was prepared that repeats words of the unrelated private request]
domains = collections.Counter()
for rel, text in texts.items():
    for m in email.finditer(text):
        domains[m.group(0).split('@', 1)[1].lower()] += 1
print('     e-mail domains that remain:', dict(domains.most_common(40)))

# 3. material of the tool that should be absent, and notices that are kept on purpose
for phrase, expect in (('You are powered by the model', 'none expected'), ('Assistant knowledge cutoff', 'none expected'),
                       ('SYSTEM NOTIFICATION - NOT USER INPUT', 'kept on purpose'), ('# userEmail', 'none expected'),
                       ('Reviewer results:', 'followed by a marker only')):
    hits = collections.Counter()
    for rel, text in texts.items():
        n = text.count(phrase)
        if n:
            hits[rel] += n
    where = ', '.join(f'{os.path.basename(k)}={v}' for k, v in hits.most_common(4))
    print(f'     phrase "{phrase}": {sum(hits.values())} ({expect}){" - " + where if hits else ""}')

# 4. the words that are private only when the assistant writes about the request: from the preparation on
kwt = re.compile(config['private_keywords_in_text'], re.I)
main_text = next(text for rel, text in texts.items() if rel.endswith(main_name))
prep = config.get('prep_start') or 10 ** 9
late = collections.Counter()
for number, line in enumerate(main_text.split('\n'), 1):
    if number > prep and kwt.search(line):
        late[f'line {number}'] += len(kwt.findall(line))
report('text-only private words in the main session after the preparation began', late)
other = collections.Counter()
for rel, text in texts.items():
    if any(run in rel for run in config.get('prep_runs', [])) or rel.endswith(('README.md', 'decision-log.md', 'completeness-declaration.md', '.csv')) and 'readable' not in rel:
        n = len(kwt.findall(text))
        if n:
            other[rel] += n
report('text-only private words in the documents, the indexes and the review runs', other)

# 5. passages of the review results (which describe the withheld material)
sources = []
for run in config.get('prep_runs', []):
    record = os.path.join(config['session_dir'], 'workflows', run + '.json')
    if os.path.exists(record):
        sources.append('\n'.join(ex.strings_of(json.load(open(record, encoding='utf-8')).get('result'))))
    journal = os.path.join(config['session_dir'], 'subagents', 'workflows', run, 'journal.jsonl')
    if os.path.exists(journal):
        for line in open(journal, encoding='utf-8'):
            try:
                item = json.loads(line)
            except ValueError:
                continue
            if 'result' in item:
                sources.append('\n'.join(ex.strings_of(item['result'])))
for name in config.get('review_dumps', []):
    path = os.path.join(X, name)
    if os.path.exists(path):
        sources.append(open(path, encoding='utf-8').read())
review = set()
for text in sources:
    review |= ex.grams_of(text, collections.Counter())
# what the reviews quote from the published text itself is not a trace of them
published = set()
for rel, text in texts.items():
    if rel.endswith(('README.md', 'decision-log.md', 'completeness-declaration.md')) or rel.startswith('export/') or rel.endswith('script.js'):
        published |= ex.grams_of(text, collections.Counter())
for number, line in enumerate(main_text.split('\n'), 1):
    if number <= prep and line.strip():
        published |= ex.grams_of('\n'.join(ex.strings_of(json.loads(line))), collections.Counter())
review -= published
shared = collections.Counter()
for rel, text in texts.items():
    if rel.endswith(('README.md', 'decision-log.md', 'completeness-declaration.md')) or rel.startswith('export/') or 'readable/' in rel or rel.endswith('.csv'):
        continue
    if rel.endswith(main_name):
        for number, line in enumerate(text.split('\n'), 1):
            if number > prep and line.strip():
                n = len(ex.grams_of('\n'.join(ex.strings_of(json.loads(line))), collections.Counter()) & review)
                if n >= 3:
                    shared[f'main line {number} ({json.loads(line).get("type")})'] += n
    else:
        n = len(ex.grams_of(text, collections.Counter()) & review)
        if n >= 3:
            shared[rel] += n
print(f'     passages known only from the review results: {len(review)}')
report('entries and files that share three or more of those passages', shared)

# 6. the candidate's prompts are there as typed
native = [json.loads(l) for l in open(config['session_file'], encoding='utf-8') if l.strip()]
staged = [json.loads(l) for l in main_text.split('\n') if l.strip()]
changed, kept = [], 0
for number, (a, b) in enumerate(zip(native, staged), 1):
    if a.get('type') == 'user' and (a.get('origin') or {}).get('kind') == 'human' and isinstance((a.get('message') or {}).get('content'), str):
        if a['message']['content'] == b['message']['content']:
            kept += 1
        else:
            changed.append(number)
print(f'     prompts of the candidate (typed messages): {kept} identical, changed in lines {changed}')
print(f'     lines: staged {len(staged)}, tool file now {len(native)}; files {len(files)}, {sum(os.path.getsize(p) for p in files) / 1e6:.1f} MB')
print('RESULT:', 'nothing to look at' if not problems else f'{problems} check(s) to look at')

